\r\\n  )\\r\\n}\\r\\n\\r\\nfunction mainPoints(\\r\\n  clearMm: number,\\r\\n  y: number,\\r\\n  z: number,\\r\\n  start: GirderEndDetail,\\r\\n  end: GirderEndDetail,\\r\\n): Rebar['points'] {\\r\\n  const points: Rebar['points'] = []\\r\\n\\r\\n  if (start.kind === '?당퇉若싩?') {\\r\\n    points.push([-start.lengthMm, y, z])\\r\\n  } else {\\r\\n    const verticalTailMm = start.lengthMm - start.projectionMm\\r\\n    const direction = start.direction === '訝? ? 1 : -1\\r\\n    points.push(\\r\\n      [\\r\\n        -start.projectionMm,\\r\\n        y + direction * verticalTailMm,\\r\\n        z,\\r\\n      ],\\r\\n      [-start.projectionMm, y, z],\\r\\n    )\\r\\n  }\\r\\n\\r\\n  if (end.kind === '?당퇉若싩?') {\\r\\n    points.push([clearMm + end.lengthMm, y, z])\\r\\n  } else {\\r\\n    const verticalTailMm = end.lengthMm - end.projectionMm\\r\\n    const direction = end.direction === '訝? ? 1 : -1\\r\\n    points.push(\\r\\n      [clearMm + end.projectionMm, y, z],\\r\\n      [\\r\\n        clearMm + end.projectionMm,\\r\\n        y + direction * verticalTailMm,\\r\\n        z,\\r\\n      ],\\r\\n    )\\r\\n  }\\r\\n\\r\\n  return points\\r\\n}\\r\\n\\r\\nfunction generateMain(\\r\\n  input: GirderRebarInput,\\r\\n  pack: RulePack,\\r\\n  coverRule: RuleHit,\\r\\n  fabricationCoverAdditionRule: RuleHit,\\r\\n  fabricationCoverMm: number,\\r\\n  row: {\\r\\n    id: 'top' | 'bottom'\\r\\n    role: '訝딁ク嶺? | '訝뗧ク嶺?\\r\\n    count: number\\r\\n    y: number\\r\\n    bendDirection: '訝? | '訝?\\r\\n  },\\r\\n): Rebar {\\r\\n  const { member, section, span } = input\\r\\n  const endInput = {\\r\\n    barSize: section.main.size,\\r\\n    fc: section.fc,\\r\\n    grade: section.grade,\\r\\n    bendDirection: row.bendDirection,\\r\\n  }\\r\\n  const start = resolveGirderEnd(\\r\\n    {\\r\\n      ...endInput,\\r\\n      supportLengthMm: span.startSupportLengthAlongAxisMm,\\r\\n      supportCover: span.startSupportCover,\\r\\n    },\\r\\n    pack,\\r\\n  )\\r\\n  const end = resolveGirderEnd(\\r\\n    {\\r\\n      ...endInput,\\r\\n      supportLengthMm: span.endSupportLengthAlongAxisMm,\\r\\n      supportCover: span.endSupportCover,\\r\\n    },\\r\\n    pack,\\r\\n  )\\r\\n  const length = span.clear + start.lengthMm + end.lengthMm\\r\\n  const zones: RebarZone[] = [\\r\\n    { kind: '若싩?', pathFromMm: 0, pathToMm: start.lengthMm },\\r\\n    {\\r\\n      kind: '若싩?',\\r\\n      pathFromMm: length - end.lengthMm,\\r\\n      pathToMm: length,\\r\\n    },\\r\\n  ]\\r\\n  const fabricationCoverFormula =\\r\\n    `?졾램?ⓦ걢?뜰굤?싥걬竊덃?弱뤵걢?뜰굤 ${coverRule.value} 竊?` +\\r\\n    `?좂츞 ${fabricationCoverAdditionRule.value} 竊?${fabricationCoverMm}竊?\\r\\n\\r\\n  return {\\r\\n    id: `${member.id}|${row.id}`,\\r\\n    memberId: member.id,\\r\\n    role: row.role,\\r\\n    size: section.main.size,\\r\\n    shape:\\r\\n      start.kind === '?섉쎊?믣츣?' || end.kind === '?섉쎊?믣츣?'\\r\\n        ? 'hook90'\\r\\n        : 'straight',\\r\\n    points: mainPoints(\\r\\n      span.clear,\\r\\n      row.y,\\r\\n      fabricationCoverMm,\\r\\n      start,\\r\\n      end,\\r\\n    ),\\r\\n    closed: false,\\r\\n    length,\\r\\n    count: row.count,\\r\\n    zones,\\r\\n    ruleHits: uniqueRuleHits([\\r\\n      coverRule,\\r\\n      fabricationCoverAdditionRule,\\r\\n      ...start.usedRules,\\r\\n      ...end.usedRules,\\r\\n    ]),\\r\\n    formula:\\r\\n      `?졾램??竊??끾퀡?룔걬 ${span.clear} 竊?${endFormula('冶뗧ク', start)} ` +\\r\\n      `竊?${endFormula('永귞ク', end)} 竊?${length} 竊?` +\\r\\n      `?띸쉰?뷸틬 竊?${fabricationCoverFormula} 竊?` +\\r\\n      `?ф빊 竊???씊訝誤㎯겗${row.role}?ф빊 ${row.count}`,\\r\\n  }\\r\\n}\\r\\n\\r\\nexport function generateGirderRebar(\\r\\n  input: GirderRebarInput,\\r\\n  pack: RulePack,\\r\\n): Rebar[] {\\r\\n  const { member, section, span } = input\\r\\n  const coverRule = lookupRule(\\r\\n    pack,\\r\\n    'cover.minimum',\\r\\n    coverConditions(section),\\r\\n  )\\r\\n  const fabricationCoverAdditionRule = lookupRule(\\r\\n    pack,\\r\\n    'cover.fabrication.addition',\\r\\n    {},\\r\\n  )\\r\\n  const minimumCoverMm = millimetres(coverRule)\\r\\n  const fabricationCoverAdditionMm = millimetres(\\r\\n    fabricationCoverAdditionRule,\\r\\n  )\\r\\n  const fabricationCoverMm =\\r\\n    minimumCoverMm + fabricationCoverAdditionMm\\r\\n\\r\\n  const top = generateMain(\\r\\n    input,\\r\\n    pack,\\r\\n    coverRule,\\r\\n    fabricationCoverAdditionRule,\\r\\n    fabricationCoverMm,\\r\\n    {\\r\\n      id: 'top',\\r\\n      role: '訝딁ク嶺?,\\r\\n      count: section.main.topCount,\\r\\n      y: section.depth - fabricationCoverMm,\\r\\n      bendDirection: '訝?,\\r\\n    },\\r\\n  )\\r\\n  const bottom = generateMain(\\r\\n    input,\\r\\n    pack,\\r\\n    coverRule,\\r\\n    fabricationCoverAdditionRule,\\r\\n    fabricationCoverMm,\\r\\n    {\\r\\n      id: 'bottom',\\r\\n      role: '訝뗧ク嶺?,\\r\\n      count: section.main.bottomCount,\\r\\n      y: fabricationCoverMm,\\r\\n      bendDirection: '訝?,\\r\\n    },\\r\\n  )\\r\\n\\r\\n  const hook135Rule = lookupRule(pack, 'bend.hook135', {})\\r\\n  const stirrupDiameter = barDiameter(section.stirrup.size)\\r\\n  const hook135LengthMm = millimetres(hook135Rule, stirrupDiameter)\\r\\n  // 誤뤸틬??媛믪씠 ?녿뒗 諛곗튂媛믪씠??????씊訝誤㏃쓽 ?낅젰??洹몃?濡??대떎 (ADR-012)\\r\\n  const startOffsetMm = section.stirrup.startOffsetMm\\r\\n  const stirrupWidthMm = section.b - 2 * fabricationCoverMm\\r\\n  const stirrupDepthMm = section.depth - 2 * fabricationCoverMm\\r\\n\\r\\n  if (stirrupWidthMm <= 0 || stirrupDepthMm <= 0) {\\r\\n    throw new MemberUnsupportedError(\\r\\n      '野멩퀡訝띷닇塋?,\\r\\n      `?귙겙?됬춮 ?졾램野멩퀡 must be positive: ${member.id} ` +\\r\\n        `(${section.b}횞${section.depth} ??2횞?졾램?ⓦ걢?뜰굤 ${fabricationCoverMm})`,\\r\\n    )\\r\\n  }\\r\\n\\r\\n  if (span.clear <= 2 * startOffsetMm) {\\r\\n    throw new MemberUnsupportedError(\\r\\n      '野멩퀡訝띷닇塋?,\\r\\n      `?귙겙?됬춮 ?띸쉰?븅뼋 must be positive: ${member.id} ` +\\r\\n        `(?끾퀡 ${span.clear} ??2횞?앮쐿?ゃ깢?삠긿??${startOffsetMm})`,\\r\\n    )\\r\\n  }\\r\\n\\r\\n  const layout = stirrupPositions(\\r\\n    span.clear,\\r\\n    section.stirrup.pitch,\\r\\n    startOffsetMm,\\r\\n  )\\r\\n  const stirrupLengthMm =\\r\\n    2 * (stirrupWidthMm + stirrupDepthMm) + 2 * hook135LengthMm\\r\\n  const fabricationCoverFormula =\\r\\n    `?졾램?ⓦ걢?뜰굤?싥걬竊덃?弱뤵걢?뜰굤 ${minimumCoverMm} 竊?` +\\r\\n    `?좂츞 ${fabricationCoverAdditionMm} 竊?${fabricationCoverMm}竊?\\r\\n  const stirrup: Rebar = {\\r\\n    id: `${member.id}|stirrup`,\\r\\n    memberId: member.id,\\r\\n    role: '?귙겙?됬춮',\\r\\n    size: section.stirrup.size,\\r\\n    shape: 'hoop',\\r\\n    points: [\\r\\n      [0, fabricationCoverMm, fabricationCoverMm],\\r\\n      [0, section.depth - fabricationCoverMm, fabricationCoverMm],\\r\\n      [\\r\\n        0,\\r\\n        section.depth - fabricationCoverMm,\\r\\n        section.b - fabricationCoverMm,\\r\\n      ],\\r\\n      [0, fabricationCoverMm, section.b - fabricationCoverMm],\\r\\n    ],\\r\\n    closed: true,\\n    length: stirrupLengthMm,\\n    count: layout.positionsMm.length,\\n    placement: { axis: 'x', clearMm: span.clear },\\n    ruleHits: [coverRule, fabricationCoverAdditionRule, hook135Rule],\\n    formula:\\r\\n      `?졾램??竊?2횞{(${section.b}??횞${fabricationCoverMm})竊? +\\r\\n      `(${section.depth}??횞${fabricationCoverMm})} 竊?` +\\r\\n      `2횞135째?뺛긿??퐰??${hook135Rule.value}d(${hook135LengthMm}) ` +\\r\\n      `竊?${stirrupLengthMm} 竊?${fabricationCoverFormula} 竊?` +\\r\\n      `?ф빊 竊??귙겙?됬춮?띸쉰竊덂냵力뺡빓??${span.clear}?? +\\r\\n      `?붵긿??${section.stirrup.pitch}?곩쭓塋?꺕永귞ク?ゃ깢?삠긿??${startOffsetMm}竊? +\\r\\n      `竊?${layout.positionsMm.length}`,\\r\\n  }\\r\\n\\r\\n  return [top, bottom, stirrup]\\r\\n}\\r\\n\\r\\nimport type { BarSize, ColumnSection, Member } from '../model/member'\\r\\nimport type { Rebar, RebarZone } from '../model/rebar'\\r\\nimport type { ColumnEnds, Story } from '../model/project'\\r\\nimport { coverConditions, lookupRule } from '../rules/lookup'\\r\\nimport type { RuleHit, RulePack } from '../rules/types'\\r\\n\\r\\nexport interface ColumnRebarInput {\\r\\n  member: Member\\r\\n  section: ColumnSection\\r\\n  story: Story\\r\\n  beamDepthAbove: number\\r\\n  /** ?ㅽ깮 ?덉뿉?쒖쓽 ?⑤? 議곌굔. `columnEnds()`媛 ?먯젙?쒕떎 (R7). */\\r\\n  ends: ColumnEnds\\r\\n}\\r\\n\\r\\nfunction barDiameter(size: BarSize): number {\\r\\n  const diameter = Number(size.replace(/^D/, ''))\\r\\n\\r\\n  if (!Number.isFinite(diameter) || diameter <= 0) {\\r\\n    throw new Error(`Invalid BarSize: ${size}`)\\r\\n  }\\r\\n\\r\\n  return diameter\\r\\n}\\r\\n\\r\\nfunction millimetres(rule: RuleHit, diameter?: number): number {\\r\\n  if (rule.unit === 'mm') return rule.value\\r\\n  if (rule.unit === 'd' && diameter !== undefined) {\\r\\n    return rule.value * diameter\\r\\n  }\\r\\n\\r\\n  throw new Error(\\r\\n    `Rule ${rule.key} must use mm or use d with a supplied bar diameter`,\\r\\n  )\\r\\n}\\r\\n\\r\\nexport function generateColumnRebar(\\r\\n  input: ColumnRebarInput,\\r\\n  pack: RulePack,\\r\\n): Rebar[] {\\r\\n  const { member, section, story, beamDepthAbove, ends } = input\\r\\n  const commonConditions = {\\r\\n    fc: section.fc,\\r\\n    grade: section.grade,\\r\\n    hook: false,\\r\\n  }\\r\\n  const coverRule = lookupRule(\\r\\n    pack,\\r\\n    'cover.minimum',\\r\\n    coverConditions(section),\\r\\n  )\\r\\n  const fabricationCoverAdditionRule = lookupRule(\\r\\n    pack,\\r\\n    'cover.fabrication.addition',\\r\\n    {},\\r\\n  )\\r\\n  // ?긴말嶺뗣겗若싩???〃5.3.4????у?L1 (力? ??力???餓ε쨼)?괢2 ??뚦돯獒귞졃鶯듽겗\\r\\n  // ?듽걹?뚣겗?ゃ걚嶸뉑??띺솏若?(力?) ?㎯곥걹??닩若싨쓲?쇻굮獒썲뱚??똻?잆겒?꾠걼?곦??уㅳ굮鵝욍걝??\\n  const anchorageRule = lookupRule(\\r\\n    pack,\\r\\n    'anchorage.L1',\\r\\n    commonConditions,\\r\\n  )\\r\\n  const lapRule = lookupRule(pack, 'lap.L1', commonConditions)\\r\\n  const hook135Rule = lookupRule(pack, 'bend.hook135', {})\\r\\n\\r\\n  const minimumCover = millimetres(coverRule)\\r\\n  const fabricationCoverAddition = millimetres(\\r\\n    fabricationCoverAdditionRule,\\r\\n  )\\r\\n  const fabricationCover = minimumCover + fabricationCoverAddition\\r\\n  const mainDiameter = barDiameter(section.main.size)\\r\\n  const anchorageLength = millimetres(anchorageRule, mainDiameter)\\r\\n  const lapLength = millimetres(lapRule, mainDiameter)\\r\\n\\r\\n  // 塋?깿?▽뻑?붵겏??섯??(R7)?귝렏?덆깿??텤?뗣겘訝딃쉸?긱걣?곥걾?곩츣???궧?욍긿??겗\\r\\n  // 訝←ク?ャ걮?뗤퍡?뗣겒?꾠귙겑?▲굢?㎯굚?ゃ걚塋?겘 0 ???멩뎸?담겎?㏂겓?겹걟?╉걚?뗣?\\n  const bottomExtension =\\r\\n    ends.bottom === '泳숁뎸' ? lapLength : anchorageLength\\r\\n  const topExtension = ends.top === '若싩?' ? anchorageLength : 0\\r\\n  const mainLength = story.height + bottomExtension + topExtension\\r\\n  const mainZones: RebarZone[] = [\\r\\n    {\\r\\n      kind: ends.bottom === '泳숁뎸' ? '?띲겖泳숁뎸' : '若싩?',\\r\\n      pathFromMm: 0,\\r\\n      pathToMm: bottomExtension,\\r\\n    },\\r\\n  ]\\r\\n\\r\\n  if (ends.top === '若싩?') {\\r\\n    mainZones.push({\\r\\n      kind: '若싩?',\\r\\n      pathFromMm: mainLength - anchorageLength,\\r\\n      pathToMm: mainLength,\\r\\n    })\\r\\n  }\\r\\n\\r\\n  const endTerms: string[] = []\\r\\n  const mainRuleHits: RuleHit[] = [\\r\\n    coverRule,\\r\\n    fabricationCoverAdditionRule,\\r\\n  ]\\r\\n\\r\\n  if (ends.bottom === '泳숁뎸') {\\r\\n    endTerms.push(\\r\\n      `訝뗧ク ?띲겖泳숁뎸?룔걬 L1 ${lapRule.value}d(${lapLength})`,\\r\\n    )\\r\\n    mainRuleHits.push(lapRule)\\r\\n  } else {\\r\\n    endTerms.push(\\r\\n      `訝뗧ク 若싩??룔걬 L1 ${anchorageRule.value}d(${anchorageLength})`,\\r\\n    )\\r\\n    mainRuleHits.push(anchorageRule)\\r\\n  }\\r\\n\\r\\n  if (ends.top === '若싩?') {\\r\\n    endTerms.push(\\r\\n      `訝딁ク 若싩??룔걬 L1 ${anchorageRule.value}d(${anchorageLength})`,\\r\\n    )\\r\\n    if (!mainRuleHits.includes(anchorageRule)) {\\r\\n      mainRuleHits.push(anchorageRule)\\r\\n    }\\r\\n  } else {\\r\\n    endTerms.push('訝딁ク 訝딃쉸?긱걣泳숁뎸?믦쿋??0')\\r\\n  }\\r\\n\\r\\n  const hoopDiameter = barDiameter(section.hoop.size)\\r\\n  const hook135Length = millimetres(hook135Rule, hoopDiameter)\\r\\n  const hoopWidth = section.b - 2 * fabricationCover\\r\\n  const hoopDepth = section.d - 2 * fabricationCover\\r\\n\\r\\n  // ?졾램?ⓦ걢?뜰굤횞2 蹂대떎 ?묒? ?⑤㈃? ?뚯닔 ?졾램?룹쓣 留뚮뱾怨? 洹?媛믪? 吏묎퀎?먯꽌\\r\\n  // 留덉씠?덉뒪 kg濡?議곗슜???섎윭媛꾨떎 ??議곗슜???由?媛?????ㅽ뙣?쒕떎 (ADR-014).\\r\\n  if (hoopWidth <= 0 || hoopDepth <= 0) {\\r\\n    throw new Error(\\r\\n      `躍?춮 ?졾램野멩퀡 must be positive: ${member.id} ` +\\r\\n        `(${section.b}횞${section.d} ??2횞?졾램?ⓦ걢?뜰굤 ${fabricationCover})`,\\r\\n    )\\r\\n  }\\r\\n\\r\\n  const hoopLength =\\r\\n    2 * (hoopWidth + hoopDepth) + 2 * hook135Length\\r\\n\\r\\n  // 訝딃깿鸚㎪쥈?쎼걚媛 ?롩쳵 ?댁긽?대㈃ 諛곗튂 援ш컙???щ씪???ф빊媛 0 ?댄븯濡??뚮떎 ??\\n  // ?졾램野멩퀡 媛?쒖? 媛숈? ?댁쑀濡??ㅽ뙣?쒕떎.\\r\\n  const hoopSpan = story.height - beamDepthAbove\\r\\n  if (hoopSpan <= 0) {\\r\\n    throw new Error(\\r\\n      `躍?춮 ?띸쉰?븅뼋 must be positive: ${member.id} ` +\\r\\n        `(?롩쳵 ${story.height} ??訝딃깿鸚㎪쥈?쎼걚 ${beamDepthAbove})`,\\r\\n    )\\r\\n  }\\r\\n\\r\\n  const hoopCount = Math.ceil(hoopSpan / section.hoop.pitch) + 1\\r\\n  const fabricationCoverFormula =\\r\\n    `?졾램?ⓦ걢?뜰굤?싥걬竊덃?弱뤵걢?뜰굤 ${minimumCover} 竊?` +\\r\\n    `?좂츞 ${fabricationCoverAddition} 竊?${fabricationCover}竊?\\r\\n\\r\\n  const main: Rebar = {\\r\\n    id: `${member.id}|main`,\\r\\n    memberId: member.id,\\r\\n    role: '訝사춮',\\r\\n    size: section.main.size,\\r\\n    shape: 'straight',\\r\\n    points: [\\r\\n      [fabricationCover, -bottomExtension, fabricationCover],\\r\\n      [\\r\\n        fabricationCover,\\r\\n        story.height + topExtension,\\r\\n        fabricationCover,\\r\\n      ],\\r\\n    ],\\r\\n    closed: false,\\r\\n    length: mainLength,\\r\\n    count: section.main.count,\\r\\n    zones: mainZones,\\r\\n    ruleHits: mainRuleHits,\\r\\n    formula:\\r\\n      `?졾램??竊??롩쳵 ${story.height} 竊?${endTerms.join(' 竊?')} ` +\\r\\n      `竊?${mainLength} 竊?` +\\r\\n      `?띸쉰?뷸틬 竊?${fabricationCoverFormula} 竊?` +\\r\\n      `?ф빊 竊???씊訝誤㎯겗訝사춮?ф빊 ${section.main.count}`,\\r\\n  }\\r\\n\\r\\n  const hoop: Reba