startOffsetMm: ${clearMm} <= ` +\\r\\n        `${2 * startOffsetMm}`,\\r\\n    )\\r\\n  }\\r\\n\\r\\n  const intervalStartMm = startOffsetMm\\r\\n  const intervalEndMm = clearMm - startOffsetMm\\r\\n  const positionsMm = [intervalStartMm]\\r\\n\\r\\n  for (let index = 1; ; index += 1) {\\r\\n    const positionMm = intervalStartMm + index * pitchMm\\r\\n    if (positionMm >= intervalEndMm) break\\r\\n    positionsMm.push(positionMm)\\r\\n  }\\r\\n\\r\\n  positionsMm.push(intervalEndMm)\\r\\n\\r\\n  for (let index = 0; index < positionsMm.length; index += 1) {\\r\\n    const positionMm = positionsMm[index]\\r\\n    if (positionMm < intervalStartMm || positionMm > intervalEndMm) {\\r\\n      throw new Error(`?귙겙?됬춮 position outside placement interval: ${positionMm}`)\\r\\n    }\\r\\n\\r\\n    if (index > 0) {\\r\\n      const gapMm = positionMm - positionsMm[index - 1]\\r\\n      if (gapMm <= 0 || gapMm > pitchMm) {\\r\\n        throw new Error(`Invalid ?귙겙?됬춮 gap: ${gapMm}`)\\r\\n      }\\r\\n    }\\r\\n  }\\r\\n\\r\\n  return {\\r\\n    positionsMm,\\r\\n    lastGapMm:\\r\\n      positionsMm[positionsMm.length - 1] -\\r\\n      positionsMm[positionsMm.length - 2],\\r\\n  }\\r\\n}\\r\\n\\r\\n'use client'\\r\\n\\r\\nimport { useMemo } from 'react'\\r\\n\\r\\nimport type { Rebar } from '@/domain/model/rebar'\\r\\nimport {\\r\\n  beamDepthAbove,\\r\\n  columnEnds,\\r\\n  findSection,\\r\\n  girderSpan,\\r\\n  girderSupport,\\r\\n  type Project,\\r\\n} from '@/domain/model/project'\\r\\nimport {\\r\\n  MemberUnsupportedError,\\r\\n  type UnsupportedReason,\\r\\n} from '@/domain/model/unsupported'\\r\\nimport {\\r\\n  aggregateQuantity,\\r\\n  hasInferred as getHasInferred,\\r\\n  inferredRules as getInferredRules,\\r\\n  type QuantityLine,\\r\\n} from '@/domain/quantity'\\r\\nimport { generateColumnRebar } from '@/domain/rebar/column'\\r\\nimport { generateGirderRebar } from '@/domain/rebar/girder'\\r\\nimport type { RuleHit } from '@/domain/rules/types'\\r\\nimport { use