r\\\\\\\\n  /** 도면에 전체 치수가 명기돼 있고 스팬 합과 일치했다 */\\\\\\\\n  totalConfirmed: boolean\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 부호가 그리드의 어디에 놓였는가 — 도면에서 잰 **기하**만 말한다.\\\\\\\\n *\\\\\\\\n * 「C면 柱」처럼 부호 접두로 부재 종별을 정하지 않는다. 종별은 断面リスト가\\\\\\\\n * 이미 갖고 있으므로(ADR-018), 취입이 그 종별과 이 기하를 맞춰 본다 —\\\\\\\\n * 어긋나면 사람이 판단할 일이지 파서가 고를 일이 아니다.\\\\\\\\n */\\\\\\\\nexport const PLAN_PLACEMENT_ROLES = ['格子点', '辺', 'ベイ'] as const\\\\\\\\n\\\\\\\\nexport type PlanPlacementRole = (typeof PLAN_PLACEMENT_ROLES)[number]\\\\\\\\n\\\\\\\\nexport interface MemberPlacement {\\\\\\\\n  mark: string\\\\\\\\n  role: PlanPlacementRole\\\\\\\\n  /** 格子点·ベイ는 격자점/베이 원점, 辺은 부재가 시작하는 격자점 */\\\\\\\\n  ix: number\\\\\\\\n  iy: number\\\\\\\\n  /** role === '辺' 일 때만 — 부재가 뻗는 방향 (GirderPosition.axis와 같은 뜻) */\\\\\\\\n  axis?: 'X' | 'Y'\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 도면 위의 伏図 한 장. 한 페이지에 여러 장이 실리므로(실물 yokohama p7은\\\\\\\\n * 2階床伏図와 R階床伏図 두 장) 通り芯 정의가 같아도 **위치가 다르다** —\\\\\\\\n * 그리드 정의는 접히지만 블록은 접히지 않는다.\\\\\\\\n */\\\\\\\\nexport interface PlanBlock {\\\\\\\\n  /** 블록 제목 원문(「2階床伏図1/100」). 어느 Story인지는 사람이 정한다 */\\\\\\\\n  title?: string\\\\\\\\n  /** 이 블록에서의 通り芯 실위치(pt). 라벨과 순서는 그리드 후보와 같다 */\\\\\\\\n  xAxes: AxisCandidate[]\\\\\\\\n  yAxes: AxisCandidate[]\\\\\\\\n  placements: MemberPlacement[]\\\\\\\\n  /** 블록 안에 있으나 스냅하지 못한 부호(중복 없음, 원문 순) — 지어내지 않는다 */\\\\\\\\n  unplacedMarks: string[]\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface ParsedFramingPlan {\\\\\\\\n  /** 通り芯 정의 — 같은 그리드가 여러 블록에 반복되면 하나로 접힌다 */\\\\\\\\n  grids: PlanGridCandidate[]\\\\\\\\n  blocks: PlanBlock[]\\\\\\\\n  /** 후보를 못 낸 사유 — 첫 등장 순, 중복 없음 */\\\\\\\\n  issues: PlanGridIssue[]\\\\\\\\n}\\\\\\\\n\\\\\\\\n/** 軸組図에서 계열을 못 낸 사유. 파서는 코드만 싣고 표시부가 번역한다 */\\\\\\\\nexport const ELEVATION_ISSUES = ['寸法列未検出'] as const\\\\\\\\n\\\\\\\\nexport type ElevationIssue = (typeof ELEVATION_ISSUES)[number]\\\\\\\\n\\\\\\\\nexport interface ElevationLevel {\\\\\\\\n  /** 그 높이에 적힌 라벨 원문 전부. 없으면 빈 배열 — 지어내지 않는다 */\\\\\\\\n  labels: string[]\\\\\\\\n  positionPt: number\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 軸組図 한 계열의 높이 방향 읽기. 「어느 레벨이 Story의 경계인가」는 정하지\\\\\\\\n * 않는다 — 원문에는 FL·GL·基礎下端·RCL이 섞여 있고, 그중 무엇이 階인지는\\\\\\\\n * 조문이 아니라 설계 의도라 사람이 읽을 일이다 (ADR-030).\\\\\\\\n *\\\\\\\\n * 通り芯과 달리 라벨의 좌우 정렬이 일정하지 않아(실물 p8의 좌단 x는 108~198로\\\\\\\\n * 흩어진다) 라벨 밴드를 앵커로 쓸 수 없다. 앵커는 **치수 열**이고, 치수가 자기\\\\\\\\n * 구간의 중점에 놓인다는 관계로 축척과 레벨 위치를 함께 푼다.\\\\\\\\n */\\\\\\\\nexport interface ElevationCandidate {\\\\\\\\n  /** 이 계열이 걸리는 軸組図 제목들(원문). 한 계열이 여러 通り에 공통으로 걸린다 */\\\\\\\\n  titles: string[]\\\\\\\\n  /** 도면 좌표 순 — 위에서 아래로 */\\\\\\\\n  levels: ElevationLevel[]\\\\\\\\n  /** 인접 레벨 사이 치수(mm). 길이는 levels.length - 1 */\\\\\\\\n  heightsMm: number[]\\\\\\\\n  scalePtPerMm: number\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface ParsedFrameElevations {\\\\\\\\n  elevations: ElevationCandidate[]\\\\\\\\n  issues: ElevationIssue[]\\\\\\\\n}\\\\\\\\n\\\\\\\\n/** 취입을 통째로 거부한 사유. 이때 案件은 손대지 않은 원본 그대로다 */\\\\\\\\nexport const PLAN_APPLY_REFUSALS = [\\\\\\\\n  '階未指定',\\\\\\\\n  '他階部材あり通り芯変更不可',\\\\\\\\n] as const\\\\\\\\n\\\\\\\\nexport type PlanApplyRefusal = (typeof PLAN_APPLY_REFUSALS)[number]\\\\\\\\n\\\\\\\\n/** 부호 하나를 넣지 못한 사유. 지어내는 대신 이 코드로 남긴다 */\\\\\\\\nexport const PLAN_APPLY_SKIPS = [\\\\\\\\n  '断面未登録',\\\\\\\\n  '部材種別相違',\\\\\\\\n  '格子外',\\\\\\\\n] as const\\\\\\\\n\\\\\\\\nexport type PlanApplySkip = (typeof PLAN_APPLY_SKIPS)[number]\\\\\\\\n\\\\\\\\n/** 階高 취입을 통째로 거부한 사유. 이때 案件은 손대지 않은 원본 그대로다 */\\\\\\\\nexport const ELEVATION_APPLY_REFUSALS = [\\\\\\\\n  '階範囲不正',\\\\\\\\n  '部材あり階置換不可',\\\\\\\\n] as const\\\\\\\\n\\\\\\\\nexport type ElevationApplyRefusal =\\\\\\\\n  (typeof ELEVATION_APPLY_REFUSALS)[number]\\\\\\\\n\\\\\\\\r\\\\\\\\nimport { compact, recoverRows, verticalRuns, type TextSegment } from '../runs'\\\\\\\\nimport type { TextItem, TextPage } from '../section-list/types'\\\\\\\\n\\\\\\\\nimport type {\\\\\\\\n  AxisCandidate,\\\\\\\\n  MemberPlacement,\\\\\\\\n  ParsedFramingPlan,\\\\\\\\n  PlanBlock,\\\\\\\\n  PlanGridCandidate,\\\\\\\\n  PlanGridIssue,\\\\\\\\n} from './types'\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 伏図의 通り芯 그리드와 부재 배치를 텍스트 레이어만으로 복원한다 (ADR-030).\\\\\\\\n *\\\\\\\\n * 실측(2026-08-23 스파이크, yokohama p5–p7·kani p38)이 준 구조:\\\\\\\\n * 축 라벨은 한 밴드(같은 x 또는 같은 y)에 늘어서고, 스팬 치수 문자열은\\\\\\\\n * 인접 라벨 좌표의 **중점**에 놓인다(실측 오차 ≤8pt). 전체 치수가 있으면\\\\\\\\n * 첫-끝 중점에 놓여 합계 검증식이 된다. 부재 부호는 격자점(柱)·변의 중점\\\\\\\\n * (大梁)·칸 중앙(床板) 중 하나에 놓인다. 벡터 선분은 쓰지 않는다 —\\\\\\\\n * 一点鎖線이 짧은 조각으로 분해돼 있고 텍스트만으로 복원이 완결된다.\\\\\\\\n */\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 通り芯 라벨 하나. 소문자 접두(b·c ＝ 棟 구분)는 실측 범위다 — 미지 표기(bX2A의\\\\\\\\n * 「A」 같은 枝番)는 지어내지 않고 정직하게 놓친다 (R10).\\\\\\\\n *\\\\\\\\n * sticky 플래그는 「이 세그먼트가 라벨의 연속으로 남김없이 설명되는가」를 묻기\\\\\\\\n * 위한 것이다 — 부분 일치를 라벨로 받으면 枝番 축이 조용히 본번으로 둔갑한다.\\\\\\\\n */\\\\\\\\nconst AXIS_LABEL_PATTERN = /[a-z]?[XY]\\\\\\\\\\\\\\\\d+/y\\\\\\\\n/** 치수 문자열 — 쉼표 구분(6,000)과 무구분(8700) 둘 다 실물에 있다 */\\\\\\\\nconst DIMENSION_PATTERN = /^(?:\\\\\\\\\\\\\\\\d{1,3}(?:,\\\\\\\\\\\\\\\\d{3})+|\\\\\\\\\\\\\\\\d{2,})$/\\\\\\\\n/**\\\\\\\\n * 부재 부호. 断面リスト의 것(section-list의 MARK_PATTERN)에 S(床板)를 더했다 —\\\\\\\\n * 伏図에는 스ラブ 부호가 나오고 리스트 표에는 나오지 않는다.\\\\\\\\n */\\\\\\\\nconst MARK_PATTERN = /^(?:C|G|FC|FG|B|CB|S|W)\\\\\\\\\\\\\\\\d+[A-Z]?$/\\\\\\\\n/** 블록 제목. 「2階床伏図1/100」처럼 축척이 붙어 오므로 부분 일치로 본다 */\\\\\\\\nconst BLOCK_TITLE_PATTERN = /伏図/\\\\\\\\n\\\\\\\\n// 실측 기반 허용오차. 근거는 스파이크 실측값이고 ADR-030에 적었다.\\\\\\\\n/** 라벨을 같은 밴드로 보는 고정 좌표 허용오차. 실측 편차는 1pt 미만이다 */\\\\\\\\nconst BAND_TOLERANCE_PT = 8\\\\\\\\n/** 치수 열이 라벨 밴드에서 떨어질 수 있는 거리. 실측 최대 50pt(kani X) */\\\\\\\\nconst DIMENSION_WINDOW_PT = 60\\\\\\\\n/** 치수 중심과 인접 축 중점의 어긋남 허용. 실측 최대 8pt, 세부 치수 연쇄의\\\\\\\\n *  최근접 오탐이 40pt라 그 사이에 둔다 */\\\\\\\\nconst MIDPOINT_TOLERANCE_PT = 15\\\\\\\\n/** 스팬별 실측 축척(pt/mm)의 중앙값 대비 허용 편차. 실측 최대 0.5% */\\\\\\\\nconst SCALE_TOLERANCE_RATIO = 0.03\\\\\\\\n/**\\\\\\\\n * 부호를 격자점·중점에 붙이는 허용 거리 ＝ 그 방향 **중앙값 스팬**의 이 비율.\\\\\\\\n *\\\\\\\\n * 인접 스팬을 쓰지 않는 이유가 있다: 실물 yokohama p7의 bX3–cX1은 1200mm(34pt)\\\\\\\\n * 짜리 좁은 띠라, 인접 스팬 기준이면 허용이 8pt로 좁아져 引出線으로 20pt쯤\\\\\\\\n * 비켜 적힌 柱 부호가 통째로 떨어진다. 중앙값은 그 좁은 띠 하나에 흔들리지 않는다.\\\\\\\\n *\\\\\\\\n * 1/4을 넘길 수는 없다 — 격자점과 중점이 반 스팬 간격이므로 1/4이 「어느 쪽에도\\\\\\\\n * 붙일 수 있다」의 경계다. 그보다 크게 잡으면 어느 쪽인지 제품이 고르게 된다.\\\\\\\\n */\\\\\\\\nconst SNAP_RATIO = 0.25\\\\\\\\n\\\\\\\\ninterface LabelToken {\\\\\\\\n  label: string\\\\\\\\n  letter: 'X' | 'Y'\\\\\\\\n  x: number\\\\\\\\n  y: number\\\\\\\\n}\\\\\\\\n\\\\\\\\ninterface PositionedToken {\\\\\\\\n  text: string\\\\\\\\n  x: number\\\\\\\\n  y: number\\\\\\\\n}\\\\\\\\n\\\\\\\\ninterface DimensionToken {\\\\\\\\n  valueMm: number\\\\\\\\n  x: number\\\\\\\\n  y: number\\\\\\\\n}\\\\\\\\n\\\\\\\\ninterface AxisSequence {\\\\\\\\n  letters: Set<'X' | 'Y'>\\\\\\\\n  /** positionPt가 어느 좌표인가 — 치수 매칭이 같은 좌표를 봐야 한다 */\\\\\\\\n  alongKey: 'x' | 'y'\\\\\\\\n  /** 밴드의 고정 좌표(평균) — 치수 창의 기준 */\\\\\\\\n  across: number\\\\\\\\n  axes: AxisCandidate[]\\\\\\\\n}\\\\\\\\n\\\\\\\\n/** 치수·축척까지 확인이 끝난 축 열. 그리드 정의와 블록이 둘 다 여기서 나온다 */\\\\\\\\ninterface ValidatedSequence extends AxisSequence {\\\\\\\\n  direction: 'X' | 'Y'\\\\\\\\n  spansMm: number[]\\\\\\\\n  scalePtPerMm: number\\\\\\\\n  totalConfirmed: boolean\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 세그먼트 하나를 라벨의 연속으로 되가른다. `makeSegments`는 표의 칸을 묶으려고\\\\\\\\n * 만든 규칙이라 인접한 두 通り芯을 한 덩이로 붙인다 — 실물 yokohama p7에서\\\\\\\\n * `bX3`(34pt 간격)와 `cX1`이 「bX3cX1」이 됐다.\\\\\\\\n *\\\\\\\\n * 되가른 라벨의 좌표는 **그 라벨을 이룬 문자들에서** 다시 잰다. 등분·보간으로\\\\\\\\n * 만들면 도면에 없는 위치를 제품이 정하는 것이 되고, 그 위치가 그대로 스팬\\\\\\\\n * 치수의 중점 판정에 쓰인다.\\\\\\\\n *\\\\\\\\n * 세그먼트 전체가 라벨로 남김없이 설명될 때만 받는다.\\\\\\\\n */\\\\\\\\nfunction splitAxisLabels(segment: TextSegment, y: number): LabelToken[] {\\\\\\\\n  // NFKC가 한 글자를 여러 글자로 펴는 경우가 있으므로 1:1을 가정하지 않고\\\\\\\\n  // 문자마다 텍스트상의 구간을 기록해 되찾는다\\\\\\\\n  let text = ''\\\\\\\\n  const spans: Array<{ start: number; end: number; item: TextItem }> = []\\\\\\\\n  for (const item of segment.items) {\\\\\\\\n    const piece = compact(item.str)\\\\\\\\n    if (piece === '') continue\\\\\\\\n    spans.push({ start: text.length, end: text.length + piece.length, item })\\\\\\\\n    text += piece\\\\\\\\n  }\\\\\\\\n  if (text === '') return []\\\\\\\\n\\\\\\\\n  const tokens: LabelToken[] = []\\\\\\\\n  AXIS_LABEL_PATTERN.lastIndex = 0\\\\\\\\n  while (AXIS_LABEL_PATTERN.lastIndex < text.length) {\\\\\\\\n    const start = AXIS_LABEL_PATTERN.lastIndex\\\\\\\\n    const match = AXIS_LABEL_PATTERN.exec(text)\\\\\\\\n    if (!match) return []\\\\\\\\n    const end = AXIS_LABEL_PATTERN.lastIndex\\\\\\\\n\\\\\\\\n    const owned = spans\\\\\\\\n      .filter((span) => span.start < end && span.end > start)\\\\\\\\n      .map((span) => span.item)\\\\\\\\n    if (owned.length === 0) return []\\\\\\\\n\\\\\\\\n    let minX = Number.POSITIVE_INFINITY\\\\\\\\n    let maxX = Number.NEGATIVE_INFINITY\\\\\\\\n    for (const item of owned) {\\\\\\\\n      if (item.x < minX) minX = item.x\\\\\\\\n      if (item.x + item.w > maxX) maxX = item.x + item.w\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    tokens.push({\\\\\\\\n      label: match[0],\\\\\\\\n      letter: match[0].includes('X') ? 'X' : 'Y',\\\\\\\\n      x: (minX + maxX) / 2,\\\\\\\\n      y,\\\\\\\\n    })\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return tokens\\\\\\\\n}\\\\\\\\n\\\\\\\\ninterface CollectedTokens {\\\\\\\\n  labels: LabelToken[]\\\\\\\\n  dimensions: DimensionToken[]\\\\\\\\n  marks: PositionedToken[]\\\\\\\\n  titles: PositionedToken[]\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction collectTokens(page: TextPage): CollectedTokens {\\\\\\\\n  const labels: LabelToken[] = []\\\\\\\\n  const dimensions: DimensionToken[] = []\\\\\\\\n  const marks: PositionedToken[] = []\\\\\\\\n  const titles: PositionedToken[] = []\\\\\\\\n\\\\\\\\n  const classify = (text: string, x: number, y: number) => {\\\\\\\\n    if (DIMENSION_PATTERN.test(text)) {\\\\\\\\n      dimensions.push({\\\\\\\\n        valueMm: Number.parseInt(text.replaceAll(',', ''), 10),\\\\\\\\n        x,\\\\\\\\n        y,\\\\\\\\n      })\\\\\\\\n      return\\\\\\\\n    }\\\\\\\\n    if (MARK_PATTERN.test(text)) {\\\\\\\\n      marks.push({ text, x, y })\\\\\\\\n      return\\\\\\\\n    }\\\\\\\\n    if (BLOCK_TITLE_PATTERN.test(text)) titles.push({ text, x, y })\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  for (const row of recoverRows(page.items)) {\\\\\\\\n    for (const segment of row.segments) {\\\\\\\\n      labels.push(...splitAxisLabels(segment, row.y))\\\\\\\\n      classify(segment.compact, segment.centerX, row.y)\\\\\\\\n    }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  // 세로쓰기는 문자 좌표가 세로로 흐르므로 되가르기를 걸지 않는다 — 실측 코퍼스의\\\\\\\\n  // 세로 런은 치수뿐이고, 세로 라벨이 붙어 나오는 도면은 빈 후보로 실패한다 (R10)\\\\\\\\n  for (const run of verticalRuns(page.items)) {\\\\\\\\n    if (/^[a-z]?[XY]\\\\\\\\\\\\\\\\d+$/.test(run.text)) {\\\\\\\\n      labels.push({\\\\\\\\n        label: run.text,\\\\\\\\n        letter: run.text.includes('X') ? 'X' : 'Y',\\\\\\\\n        x: run.x,\\\\\\\\n        y: run.y,\\\\\\\\n      })\\\\\\\\n      continue\\\\\\\\n    }\\\\\\\\n    classify(run.text, run.x, run.y)\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return { labels, dimensions, marks, titles }\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 라벨들을 고정 좌표가 이어지는 밴드로 묶고, 밴드 안에서 위치 오름차순으로\\\\\\\\n * 늘어놓은 뒤 라벨이 반복되는 자리에서 갈라 축 열을 만든다 — 한 페이지에\\\\\\\\n * 같은 그리드의 伏図가 여러 블록 있으면(실물 p7) 같은 밴드에 열이 반복된다.\\\\\\\\n */\\\\\\\\nfunction axisSequences(\\\\\\\\n  labels: LabelToken[],\\\\\\\\n  across: 'x' | 'y',\\\\\\\\n): AxisSequence[] {\\\\\\\\n  const along = across === 'x' ? 'y' : 'x'\\\\\\\\n  const sorted = [...labels].sort((a, b) => a[across] - b[across])\\\\\\\\n  const bands: LabelToken[][] = []\\\\\\\\n\\\\\\\\n  for (const token of sorted) {\\\\\\\\n    const band = bands.at(-1)\\\\\\\\n    const previous = band?.at(-1)\\\\\\\\n    if (\\\\\\\\n      band &&\\\\\\\\n      previous &&\\\\\\\\n      token[across] - previous[across] <= BAND_TOLERANCE_PT\\\\\\\\n    ) {\\\\\\\\n      band.push(token)\\\\\\\\n    } else {\\\\\\\\n      bands.push([token])\\\\\\\\n    }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  const sequences: AxisSequence[] = []\\\\\\\\n  for (const band of bands) {\\\\\\\\n    if (band.length < 2) continue\\\\\\\\n    const ordered = [...band].sort((a, b) => a[along] - b[along])\\\\\\\\n\\\\\\\\n    let current: LabelToken[] = []\\\\\\\\n    const flush = () => {\\\\\\\\n      if (current.length >= 2) {\\\\\\\\n        sequences.push({\\\\\\\\n          letters: new Set(current.map((token) => token.letter)),\\\\\\\\n          alongKey: along,\\\\\\\\n          across:\\\\\\\\n            current.reduce((total, token) => total + token[across], 0) /\\\\\\\\n            current.length,\\\\\\\\n          axes: current.map((token) => ({\\\\\\\\n            label: token.label,\\\\\\\\n            positionPt: token[along],\\\\\\\\n          })),\\\\\\\\n        })\\\\\\\\n      }\\\\\\\\n      current = []\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    for (const token of ordered) {\\\\\\\\n      if (current.some((seen) => seen.label === token.label)) flush()\\\\\\\\n      current.push(token)\\\\\\\\n    }\\\\\\\\n    flush()\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return sequences\\\\\\\\n}\\\\\\\\n\\\\\\\\n/** 인접 축 쌍의 중점에서, 라벨 밴드의 치수 창 안에 있는 치수를 찾는다 */\\\\\\\\nfunction dimensionAt(\\\\\\\\n  dimensions: DimensionToken[],\\\\\\\\n  used: Set<DimensionToken>,\\\\\\\\n  along: 'x' | 'y',\\\\\\\\n  across: 'x' | 'y',\\\\\\\\n  midpoint: number,\\\\\\\\n  bandAcross: number,\\\\\\\\n): DimensionToken | undefined {\\\\\\\\n  let best: DimensionToken | undefined\\\\\\\\n  let bestDistance = Number.POSITIVE_INFINITY\\\\\\\\n\\\\\\\\n  for (const token of dimensions) {\\\\\\\\n    if (used.has(token)) continue\\\\\\\\n    const alongDistance = Math.abs(token[along] - midpoint)\\\\\\\\n    if (alongDistance > MIDPOINT_TOLERANCE_PT) continue\\\\\\\\n    if (Math.abs(token[across] - bandAcross) > DIMENSION_WINDOW_PT) continue\\\\\\\\n    if (alongDistance < bestDistance) {\\\\\\\\n      best = token\\\\\\\\n      bestDistance = alongDistance\\\\\\\\n    }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return best\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction median(values: number[]): number {\\\\\\\\n  return [...values].sort((a, b) => a - b)[Math.floor(values.length / 2)]\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction validateSequence(\\\\\\\\n  sequence: AxisSequence,\\\\\\\\n  dimensions: DimensionToken[],\\\\\\\\n  issue: (code: PlanGridIssue) => void,\\\\\\\\n): ValidatedSequence | undefined {\\\\\\\\n  if (sequence.letters.size > 1) {\\\\\\\\n    issue('ラベル文字混在')\\\\\\\\n    return undefined\\\\\\\\n  }\\\\\\\\n  const alongKey = sequence.alongKey\\\\\\\\n  const acrossKey: 'x' | 'y' = alongKey === 'y' ? 'x' : 'y'\\\\\\\\n\\\\\\\\n  const used = new Set<DimensionToken>()\\\\\\\\n  const spans: DimensionToken[] = []\\\\\\\\n  for (let i = 0; i + 1 < sequence.axes.length; i++) {\\\\\\\\n    const midpoint =\\\\\\\\n      (sequence.axes[i].positionPt + sequence.axes[i + 1].positionPt) / 2\\\\\\\\n    const dimension = dimensionAt(\\\\\\\\n      dimensions,\\\\\\\\n      used,\\\\\\\\n      alongKey,\\\\\\\\n      acrossKey,\\\\\\\\n      midpoint,\\\\\\\\n      sequence.across,\\\\\\\\n    )\\\\\\\\n    if (!dimension) break\\\\\\\\n    used.add(dimension)\\\\\\\\n    spans.push(dimension)\\\\\\\\n  }\\\\\\\\n  if (spans.length < sequence.axes.length - 1) {\\\\\\\\n    issue('寸法欠落')\\\\\\\\n    return undefined\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  // 스팬별 실측 축척이 갈리면 치수 오배정이다 — 조용한 그리드를 내느니 실패한다\\\\\\\\n  const scales = spans.map(\\\\\\\\n    (span, i) =>\\\\\\\\n      (sequence.axes[i + 1].positionPt - sequence.axes[i].positionPt) /\\\\\\\\n      span.valueMm,\\\\\\\\n  )\\\\\\\\n  const medianScale = median(scales)\\\\\\\\n  if (\\\\\\\\n    scales.some(\\\\\\\\n      (scale) => Math.abs(scale / medianScale - 1) > SCALE_TOLERANCE_RATIO,\\\\\\\\n    )\\\\\\\\n  ) {\\\\\\\\n    issue('縮尺不整合')\\\\\\\\n    return undefined\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  // 전체 치수(첫-끝 중점)가 있으면 합계 검증식으로 쓴다 — 불일치는 오독 신호다\\\\\\\\n  const spanSum = spans.reduce((sum, span) => sum + span.valueMm, 0)\\\\\\\\n  const first = sequence.axes[0].positionPt\\\\\\\\n  const last = sequence.axes.at(-1)?.positionPt ?? first\\\\\\\\n  const total = dimensionAt(\\\\\\\\n    dimensions,\\\\\\\\n    used,\\\\\\\\n    alongKey,\\\\\\\\n    acrossKey,\\\\\\\\n    (first + last) / 2,\\\\\\\\n    sequence.across,\\\\\\\\n  )\\\\\\\\n  if (total && total.valueMm !== spanSum) {\\\\\\\\n    issue('合計不一致')\\\\\\\\n    return undefined\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return {\\\\\\\\n    ...sequence,\\\\\\\\n    direction: [...sequence.letters][0],\\\\\\\\n    spansMm: spans.map((span) => span.valueMm),\\\\\\\\n    scalePtPerMm: medianScale,\\\\\\\\n    totalConfirmed: total !== undefined,\\\\\\\\n  }\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction extent(axes: AxisCandidate[]): { min: number; max: number } {\\\\\\\\n  return {\\\\\\\\n    min: axes[0].positionPt,\\\\\\\\n    max: axes[axes.length - 1].positionPt,\\\\\\\\n  }\\\\\\\\n}\\\\\\\\n\\\\\\\\n/** 점에서 구간까지의 거리. 구간 안이면 0 */\\\\\\\\nfunction distanceToRange(value: number, min: number, max: number): number {\\\\\\\\n  if (value < min) return min - value\\\\\\\\n  if (value > max) return value - max\\\\\\\\n  return 0\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 부호가 붙는 자리를 만든다 — 격자점과 그 사이 중점이 번갈아 놓인 눈금이다.\\\\\\\\n * 짝수 index가 격자점(index/2), 홀수가 중점(사이 (index-1)/2).\\\\\\\\n */\\\\\\\\nfunction snapTargets(axes: AxisCandidate[]): number[] {\\\\\\\\n  const targets: number[] = []\\\\\\\\n  for (let i = 0; i < axes.length; i++) {\\\\\\\\n    targets.push(axes[i].positionPt)\\\\\\\\n    if (i + 1 < axes.length) {\\\\\\\\n      targets.push((axes[i].positionPt + axes[i + 1].positionPt) / 2)\\\\\\\\n    }\\\\\\\\n  }\\\\\\\\n  return targets\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction spanLengths(axes: AxisCandidate[]): number[] {\\\\\\\\n  return axes\\\\\\\\n    .slice(1)\\\\\\\\n    .map((axis, i) => axis.positionPt - axes[i].positionPt)\\\\\\\\n}\\\\\\\\n\\\\\\\\ninterface Snap {\\\\\\\\n  index: number\\\\\\\\n  onNode: boolean\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction snap(\\\\\\\\n  value: number,\\\\\\\\n  axes: AxisCandidate[],\\\\\\\\n  limit: number,\\\\\\\\n): Snap | undefined {\\\\\\\\n  const targets = snapTargets(axes)\\\\\\\\n  let best = -1\\\\\\\\n  let bestDistance = Number.POSITIVE_INFINITY\\\\\\\\n  for (let i = 0; i < targets.length; i++) {\\\\\\\\n    const distance = Math.abs(targets[i] - value)\\\\\\\\n    if (distance < bestDistance) {\\\\\\\\n      best = i\\\\\\\\n      bestDistance = distance\\\\\\\\n    }\\\\\\\\n  }\\\\\\\\n  if (best < 0 || bestDistance > limit) return undefined\\\\\\\\n  return { index: best >> 1, onNode: best % 2 === 0 }\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction placementFor(\\\\\\\\n  mark: string,\\\\\\\\n  x: Snap,\\\\\\\\n  y: Snap,\\\\\\\\n): MemberPlacement | undefined {\\\\\\\\n  if (x.onNode && y.onNode) {\\\\\\\\n    return { mark, role: '格子点', ix: x.index, iy: y.index }\\\\\\\\n  }\\\\\\\\n  if (!x.onNode && y.onNode) {\\\\\\\\n    return { mark, role: '辺', ix: x.index, iy: y.index, axis: 'X' }\\\\\\\\n  }\\\\\\\\n  if (x.onNode && !y.onNode) {\\\\\\\\n    return { mark, role: '辺', ix: x.index, iy: y.index, axis: 'Y' }\\\\\\\\n  }\\\\\\\\n  return { mark, role: 'ベイ', ix: x.index, iy: y.index }\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 블록을 짓는다 — X 열 하나와 **가장 가까운** Y 열 하나를 짝짓는다.\\\\\\\\n *\\\\\\\\n * 고정 여백으로 「포함」을 판정하지 않는 이유: 라벨은 도면 바깥에 놓이므로\\\\\\\\n * 여백이 필요한데(실물 156pt), 그 여백을 넓히면 옆 블록의 열까지 삼킨다.\\\\\\\\n * 최근접은 그 사이를 재지 않고도 옳은 짝을 고른다.\\\\\\\\n *\\\\\\\\n * 같은 블록의 위·아래 라벨 띠는 축 위치가 같으므로 그 자리에서 하나로 접힌다.\\\\\\\\n */\\\\\\\\nfunction buildBlocks(\\\\\\\\n  xSequences: ValidatedSequence[],\\\\\\\\n  ySequences: ValidatedSequence[],\\\\\\\\n  marks: PositionedToken[],\\\\\\\\n  titles: PositionedToken[],\\\\\\\\n): PlanBlock[] {\\\\\\\\n  const blocks: PlanBlock[] = []\\\\\\\\n  const seen = new Set<string>()\\\\\\\\n\\\\\\\\n  for (const xSequence of xSequences) {\\\\\\\\n    const xExtent = extent(xSequence.axes)\\\\\\\\n    let paired: ValidatedSequence | undefined\\\\\\\\n    let pairedDistance = Number.POSITIVE_INFINITY\\\\\\\\n    for (const ySequence of ySequences) {\\\\\\\\n      const distance = distanceToRange(\\\\\\\\n        ySequence.across,\\\\\\\\n        xExtent.min,\\\\\\\\n        xExtent.max,\\\\\\\\n      )\\\\\\\\n      if (distance < pairedDistance) {\\\\\\\\n        paired = ySequence\\\\\\\\n        pairedDistance = distance\\\\\\\\n      }\\\\\\\\n    }\\\\\\\\n    if (!paired) continue\\\\\\\\n\\\\\\\\n    const xAxes = xSequence.axes\\\\\\\\n    const yAxes = paired.axes\\\\\\\\n    const key = [xAxes, yAxes]\\\\\\\\n      .map((axes) =>\\\\\\\\n        axes\\\\\\\\n          .map((axis) => `${axis.label}@${Math.round(axis.positionPt)}`)\\\\\\\\n          .join(','),\\\\\\\\n      )\\\\\\\\n      .join('|')\\\\\\\\n    if (seen.has(key)) continue\\\\\\\\n    seen.add(key)\\\\\\\\n\\\\\\\\n    const xLimit = median(spanLengths(xAxes)) * SNAP_RATIO\\\\\\\\n    const yLimit = median(spanLengths(yAxes)) * SNAP_RATIO\\\\\\\\n    const yExtent = extent(yAxes)\\\\\\\\n\\\\\\\\n    const placements: MemberPlacement[] = []\\\\\\\\n    const unplacedMarks: string[] = []\\\\\\\\n    for (const mark of marks) {\\\\\\\\n      // 블록 밖의 부호는 아예 보지 않는다 — 같은 페이지의 断面リスト가 섞인다.\\\\\\\\n      // 판정 여백을 스냅 허용과 같게 두어, 「블록 안인데 못 붙였다」와\\\\\\\\n      // 「블록 밖이다」가 같은 자로 갈리게 한다\\\\\\\\n      if (distanceToRange(mark.x, xExtent.min, xExtent.max) > xLimit) continue\\\\\\\\n      if (distanceToRange(mark.y, yExtent.min, yExtent.max) > yLimit) continue\\\\\\\\n\\\\\\\\n      const x = snap(mark.x, xAxes, xLimit)\\\\\\\\n      const y = snap(mark.y, yAxes, yLimit)\\\\\\\\n      if (!x || !y) {\\\\\\\\n        if (!unplacedMarks.includes(mark.text)) unplacedMarks.push(mark.text)\\\\\\\\n        continue\\\\\\\\n      }\\\\\\\\n      const placement = placementFor(mark.text, x, y)\\\\\\\\n      if (placement) placements.push(placement)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    // 제목은 블록의 가로 범위 안에 있는 것만 본다 — 나란히 선 두 伏図에서\\\\\\\\n    // 세로 거리만으로 고르면 옆 블록의 제목이 붙는다\\\\\\\\n    let title: string | undefined\\\\\\\\n    let titleDistance = Number.POSITIVE_INFINITY\\\\\\\\n    for (const candidate of titles) {\\\\\\\\n      if (distanceToRange(candidate.x, xExtent.min, xExtent.max) > 0) continue\\\\\\\\n      const distance = distanceToRange(candidate.y, yExtent.min, yExtent.max)\\\\\\\\n      if (distance < titleDistance) {\\\\\\\\n        title = candidate.text\\\\\\\\n        titleDistance = distance\\\\\\\\n      }\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    blocks.push({\\\\\\\\n      ...(title === undefined ? {} : { title }),\\\\\\\\n      xAxes,\\\\\\\\n      yAxes,\\\\\\\\n      placements,\\\\\\\\n      unplacedMarks,\\\\\\\\n    })\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return blocks.sort(\\\\\\\\n    (a, b) =>\\\\\\\\n      a.xAxes[0].positionPt - b.xAxes[0].positionPt ||\\\\\\\\n      a.yAxes[0].positionPt - b.yAxes[0].positionPt,\\\\\\\\n  )\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport function parseFramingPlan(page: TextPage): ParsedFramingPlan {\\\\\\\\n  const { labels, dimensions, marks, titles } = collectTokens(page)\\\\\\\\n\\\\\\\\n  const issues: PlanGridIssue[] = []\\\\\\\\n  const issue = (code: PlanGridIssue) => {\\\\\\\\n    if (!issues.includes(code)) issues.push(code)\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  if (labels.length === 0) {\\\\\\\\n    return { grids: [], blocks: [], issues: ['通り芯ラベル未検出'] }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  // 라벨 문자열이 가로로 놓여도 밴드(축의 늘어선 방향)는 세로일 수 있다 —\\\\\\\\n  // 두 방향 다 묶어 보고, 검증(중점 치수·축척)이 가짜 밴드를 걸러낸다.\\\\\\\\n  const validated = [\\\\\\\\n    ...axisSequences(labels, 'x'),\\\\\\\\n    ...axisSequences(labels, 'y'),\\\\\\\\n  ].flatMap((sequence) => {\\\\\\\\n    const result = validateSequence(sequence, dimensions, issue)\\\\\\\\n    return result ? [result] : []\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  const grids: PlanGridCandidate[] = []\\\\\\\\n  const seen = new Set<string>()\\\\\\\\n  for (const sequence of validated) {\\\\\\\\n    const candidate: PlanGridCandidate = {\\\\\\\\n      direction: sequence.direction,\\\\\\\\n      axes: sequence.axes,\\\\\\\\n      spansMm: sequence.spansMm,\\\\\\\\n      scalePtPerMm: sequence.scalePtPerMm,\\\\\\\\n      totalConfirmed: sequence.totalConfirmed,\\\\\\\\n    }\\\\\\\\n    const key = [\\\\\\\\n      candidate.direction,\\\\\\\\n      candidate.axes.map((axis) => axis.label).join(','),\\\\\\\\n      candidate.spansMm.join(','),\\\\\\\\n    ].join('|')\\\\\\\\n    if (seen.has(key)) continue\\\\\\\\n    seen.add(key)\\\\\\\\n    grids.push(candidate)\\\\\\\\n  }\\\\\\\\n  grids.sort(\\\\\\\\n    (a, b) =>\\\\\\\\n      a.direction.localeCompare(b.direction) ||\\\\\\\\n      a.axes[0].positionPt - b.axes[0].positionPt,\\\\\\\\n  )\\\\\\\\n\\\\\\\\n  const blocks = buildBlocks(\\\\\\\\n    validated.filter((sequence) => sequence.direction === 'X'),\\\\\\\\n    validated.filter((sequence) => sequence.direction === 'Y'),\\\\\\\\n    marks,\\\\\\\\n    titles,\\\\\\\\n  )\\\\\\\\n\\\\\\\\n  return { grids, blocks, issues }\\\\\\\\n}\\\\\\\\n\\\\\\\\r\\\\\\\\nimport type { Member, MemberKind, Section } from '@/domain/model/member'\\\\\\\\nimport type { Grid, Project, Story } from '@/domain/model/project'\\\\\\\\n\\\\\\\\nimport type {\\\\\\\\n  ElevationApplyRefusal,\\\\\\\\n  ElevationCandidate,\\\\\\\\n  PlanApplyRefusal,\\\\\\\\n  PlanApplySkip,\\\\\\\\n  PlanBlock,\\\\\\\\n  PlanGridCandidate,\\\\\\\\n  PlanPlacementRole,\\\\\\\\n  MemberPlacement,\\\\\\\\n} from './types'\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 伏図에서 읽은 형상을 案件에 반영한다 (ADR-030).\\\\\\\\n *\\\\\\\\n * 断面リスト 취입(ADR-018)과 같은 자리에 선다 — 사용자가 승인한 뒤에만 불리고,\\\\\\\\n * 반영하지 못한 것은 지어내지 않고 사유와 함께 돌려준다.\\\\\\\\n */\\\\\\\\n\\\\\\\\n/** 種別이 놓일 수 있는 자리. 조문이 아니라 형상의 정의다 */\\\\\\\\nconst ROLE_FOR_KIND: Record<MemberKind, PlanPlacementRole> = {\\\\\\\\n  柱: '格子点',\\\\\\\\n  大梁: '辺',\\\\\\\\n  耐震壁: '辺',\\\\\\\\n  床板: 'ベイ',\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface PlanApplyOptions {\\\\\\\\n  xGrid: PlanGridCandidate\\\\\\\\n  yGrid: PlanGridCandidate\\\\\\\\n  block: PlanBlock\\\\\\\\n  storyId: string\\\\\\\\n  /**\\\\\\\\n   * 通り芯이 바뀔 때 다른 층의 부재를 버리고 진행한다. 기본은 false이고,\\\\\\\\n   * 화면은 거부를 한 번 보여준 뒤에만 이 선택지를 낸다 — 조용한 기본값으로\\\\\\\\n   * 두면 사용자가 모르는 사이에 다른 층이 사라진다\\\\\\\\n   */\\\\\\\\n  discardOtherStories?: boolean\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface PlanApplyResult {\\\\\\\\n  project: Project\\\\\\\\n  /** 반영한 부재 수 */\\\\\\\\n  applied: number\\\\\\\\n  /** 반영하지 못한 부호와 사유 — 원문 순, 같은 부호가 여러 번 걸리면 여러 번 */\\\\\\\\n  skipped: Array<{ mark: string; reason: PlanApplySkip }>\\\\\\\\n  /** 통째로 거부한 사유. 있으면 project는 손대지 않은 원본 그대로다 */\\\\\\\\n  refusal?: PlanApplyRefusal\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction gridOf(\\\\\\\\n  xGrid: PlanGridCandidate,\\\\\\\\n  yGrid: PlanGridCandidate,\\\\\\\\n): Grid {\\\\\\\\n  return {\\\\\\\\n    xSpans: [...xGrid.spansMm],\\\\\\\\n    ySpans: [...yGrid.spansMm],\\\\\\\\n    // 通り芯의 이름은 도면에 있는 것이고, 이것이 있어야 「Y3端／Y4端」처럼\\\\\\\\n    // 좌우가 다른 断面リスト를 런의 실제 방향과 맞출 수 있다 (R13의 선결 조건)\\\\\\\\n    xLabels: xGrid.axes.map((axis) => axis.label),\\\\\\\\n    yLabels: yGrid.axes.map((axis) => axis.label),\\\\\\\\n  }\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 스팬만 본다 — 라벨은 数量도 격자 index도 바꾸지 않으므로, 이름만 달라진\\\\\\\\n * 그리드를 「바뀌었다」로 보면 다른 층의 부재를 버리라는 물음이 이유 없이 뜬다.\\\\\\\\n */\\\\\\\\nfunction sameGrid(left: Grid, right: Grid): boolean {\\\\\\\\n  return (\\\\\\\\n    left.xSpans.length === right.xSpans.length &&\\\\\\\\n    left.ySpans.length === right.ySpans.length &&\\\\\\\\n    left.xSpans.every((span, i) => span === right.xSpans[i]) &&\\\\\\\\n    left.ySpans.every((span, i) => span === right.ySpans[i])\\\\\\\\n  )\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction positionOf(placement: MemberPlacement) {\\\\\\\\n  return placement.role === '辺'\\\\\\\\n    ? { axis: placement.axis ?? 'X', ix: placement.ix, iy: placement.iy }\\\\\\\\n    : { ix: placement.ix, iy: placement.iy }\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 배치가 격자 안을 가리키는가. 辺은 부재가 뻗는 쪽으로 한 칸 더 필요하고,\\\\\\\\n * ベイ는 원점 쪽 격자점이므로 양쪽으로 한 칸씩 남아야 한다.\\\\\\\\n */\\\\\\\\nfunction withinGrid(placement: MemberPlacement, grid: Grid): boolean {\\\\\\\\n  const nx = grid.xSpans.length + 1\\\\\\\\n  const ny = grid.ySpans.length + 1\\\\\\\\n  const lastIx =\\\\\\\\n    placement.role === 'ベイ' || (placement.role === '辺' && placement.axis === 'X')\\\\\\\\n      ? nx - 2\\\\\\\\n      : nx - 1\\\\\\\\n  const lastIy =\\\\\\\\n    placement.role === 'ベイ' || (placement.role === '辺' && placement.axis === 'Y')\\\\\\\\n      ? ny - 2\\\\\\\\n      : ny - 1\\\\\\\\n\\\\\\\\n  return (\\\\\\\\n    placement.ix >= 0 &&\\\\\\\\n    placement.ix <= lastIx &&\\\\\\\\n    placement.iy >= 0 &&\\\\\\\\n    placement.iy <= lastIy\\\\\\\\n  )\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport function applyFramingPlan(\\\\\\\\n  project: Project,\\\\\\\\n  { xGrid, yGrid, block, storyId, discardOtherStories = false }: PlanApplyOptions,\\\\\\\\n): PlanApplyResult {\\\\\\\\n  if (!project.stories.some((story) => story.id === storyId)) {\\\\\\\\n    return { project, applied: 0, skipped: [], refusal: '階未指定' }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  const grid = gridOf(xGrid, yGrid)\\\\\\\\n  const changesGrid = !sameGrid(project.grid, grid)\\\\\\\\n  const otherStoryMembers = project.members.some(\\\\\\\\n    (member) => member.storyId !== storyId,\\\\\\\\n  )\\\\\\\\n  // 격자 index는 스팬 배열에 매여 있다 — 스팬을 바꾸면 손대지 않은 층의 부재가\\\\\\\\n  // 조용히 다른 자리로 옮겨간다. 부분 반영으로 넘어가면 「틀린 채로 완성된 것」이\\\\\\\\n  // 되므로 통째로 거부하고, 어느 쪽을 버릴지는 사용자가 정한다\\\\\\\\n  if (changesGrid && otherStoryMembers && !discardOtherStories) {\\\\\\\\n    return {\\\\\\\\n      project,\\\\\\\\n      applied: 0,\\\\\\\\n      skipped: [],\\\\\\\\n      refusal: '他階部材あり通り芯変更不可',\\\\\\\\n    }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  const sections = new Map<string, Section>()\\\\\\\\n  for (const section of project.sections) {\\\\\\\\n    if (!sections.has(section.mark)) sections.set(section.mark, section)\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  const members: Member[] = []\\\\\\\\n  const skipped: PlanApplyResult['skipped'] = []\\\\\\\\n  for (const placement of block.placements) {\\\\\\\\n    const section = sections.get(placement.mark)\\\\\\\\n    if (!section) {\\\\\\\\n      skipped.push({ mark: placement.mark, reason: '断面未登録' })\\\\\\\\n      continue\\\\\\\\n    }\\\\\\\\n    if (ROLE_FOR_KIND[section.kind] !== placement.role) {\\\\\\\\n      skipped.push({ mark: placement.mark, reason: '部材種別相違' })\\\\\\\\n      continue\\\\\\\\n    }\\\\\\\\n    if (!withinGrid(placement, grid)) {\\\\\\\\n      skipped.push({ mark: placement.mark, reason: '格子外' })\\\\\\\\n      continue\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    members.push({\\\\\\\\n      // id는 사람이 읽는 값이 아니라 충돌만 피하면 된다. 같은 자리에 같은 符号을\\\\\\\\n      // 두 번 반영해도 하나로 접히도록 자리를 id에 넣는다\\\\\\\\n      id: `${storyId}-${placement.mark}-${placement.ix}-${placement.iy}`,\\\\\\\\n      kind: section.kind,\\\\\\\\n      memberClass: '躯体',\\\\\\\\n      sectionId: section.id,\\\\\\\\n      storyId,\\\\\\\\n      position: positionOf(placement),\\\\\\\\n    } as Member)\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  const deduped = new Map<string, Member>()\\\\\\\\n  for (const member of members) deduped.set(member.id, member)\\\\\\\\n\\\\\\\\n  return {\\\\\\\\n    project: {\\\\\\\\n      ...project,\\\\\\\\n      grid,\\\\\\\\n      // 취입하는 층은 갈아 끼운다 — 두 번 눌러도 겹치지 않아야 하고, 도면에서\\\\\\\\n      // 사라진 부재가 案件에 남아 있으면 그것도 「틀린 채로 완성된 것」이다\\\\\\\\n      members: [\\\\\\\\n        // 통り芯이 바뀌면 남은 부재의 index가 다른 자리를 가리키게 되므로,\\\\\\\\n        // 동의를 받았을 때는 남기지 않고 전부 버린다 — 반쯤 옮겨 놓느니 비운다\\\\\\\\n        ...(changesGrid && discardOtherStories\\\\\\\\n          ? []\\\\\\\\n          : project.members.filter((member) => member.storyId !== storyId)),\\\\\\\\n        ...deduped.values(),\\\\\\\\n      ],\\\\\\\\n    },\\\\\\\\n    applied: deduped.size,\\\\\\\\n    skipped,\\\\\\\\n  }\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface ElevationApplyOptions {\\\\\\\\n  candidate: ElevationCandidate\\\\\\\\n  /**\\\\\\\\n   * 階의 경계로 쓸 레벨의 범위. index는 **도면 순서**(위에서 아래)다.\\\\\\\\n   * 위 끝(top)이 최상階의 천장, 아래 끝(bottom)이 최하階의 바닥이 된다 —\\\\\\\\n   * パラペット 천단이나 基礎下端처럼 階가 아닌 레벨은 범위 밖에 둔다.\\\\\\\\n   */\\\\\\\\n  topLevelIndex: number\\\\\\\\n  bottomLevelIndex: number\\\\\\\\n  /** 階를 갈면 부재가 갈 곳을 잃는다. 화면은 거부를 보여준 뒤에만 이 선택지를 낸다 */\\\\\\\\n  discardMembers?: boolean\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface ElevationApplyResult {\\\\\\\\n  project: Project\\\\\\\\n  /** 만든 階 수 */\\\\\\\\n  applied: number\\\\\\\\n  refusal?: ElevationApplyRefusal\\\\\\\\n}\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 軸組図에서 읽은 높이를 案件의 階로 반영한다 (ADR-030).\\\\\\\\n *\\\\\\\\n * 「어느 레벨이 階의 경계인가」는 파서가 정하지 않으므로(FL·GL·基礎下端·RCL이\\\\\\\\n * 섞여 있다) 여기서 사용자의 선택을 받는다. 階의 이름도 지어내지 않고 그 階의\\\\\\\\n * **바닥이 되는 레벨의 원문**을 그대로 쓴다 — 같은 높이에 라벨이 둘이면 둘 다\\\\\\\\n * 남긴다(실물의 「中央棟1FL」과 「基準GL」이 그렇다).\\\\\\\\n */\\\\\\\\nexport function applyElevation(\\\\\\\\n  project: Project,\\\\\\\\n  {\\\\\\\\n    candidate,\\\\\\\\n    topLevelIndex,\\\\\\\\n    bottomLevelIndex,\\\\\\\\n    discardMembers = false,\\\\\\\\n  }: ElevationApplyOptions,\\\\\\\\n): ElevationApplyResult {\\\\\\\\n  const valid =\\\\\\\\n    Number.isInteger(topLevelIndex) &&\\\\\\\\n    Number.isInteger(bottomLevelIndex) &&\\\\\\\\n    topLevelIndex >= 0 &&\\\\\\\\n    bottomLevelIndex > topLevelIndex &&\\\\\\\\n    bottomLevelIndex < candidate.levels.length\\\\\\\\n  if (!valid) {\\\\\\\\n    return { project, applied: 0, refusal: '階範囲不正' }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  // 階를 갈면 부재의 storyId가 가리키던 階가 사라진다. 부분 반영으로 넘어가면\\\\\\\\n  // 「틀린 채로 완성된 것」이 되므로 통째로 거부하고, 사용자가 정한다\\\\\\\\n  if (project.members.length > 0 && !discardMembers) {\\\\\\\\n    return { project, applied: 0, refusal: '部材あり階置換不可' }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  const stories: Story[] = []\\\\\\\\n  // 도면은 위에서 아래, `Project.stories`는 아래에서 위다 (columnEnds가\\\\\\\\n  // stories[level - 1]을 「아래 階」로 읽는다)\\\\\\\\n  for (let i = bottomLevelIndex - 1; i >= topLevelIndex; i--) {\\\\\\\\n    const floor = candidate.levels[i + 1]\\\\\\\\n    const name =\\\\\\\\n      floor.labels.length > 0\\\\\\\\n        ? floor.labels.join('／')\\\\\\\\n        : `${bottomLevelIndex - i}`\\\\\\\\n    stories.push({\\\\\\\\n      id: `story-${bottomLevelIndex - i}`,\\\\\\\\n      name,\\\\\\\\n      height: candidate.heightsMm[i],\\\\\\\\n    })\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return {\\\\\\\\n    project: { ...project, stories, members: [] },\\\\\\\\n    applied: stories.length,\\\\\\\\n  }\\\\\\\\n}\\\\\\\\n\\\\\\\\r\\\\\\\\nimport { describe, expect, it } from 'vitest'\\\\\\\\n\\\\\\\\nimport type { TextItem, TextPage } from '../section-list/types'\\\\\\\\n\\\\\\\\nimport { parseFramingPlan } from './parse'\\\\\\\\n\\\\\\\\n// 실물 도면 픽스처 대조는 tests/plan-import/parse.test.ts에 있다.\\\\\\\\n// 여기는 합성 TextPage로 파서의 경계 규칙만 고정한다 (section-list와 같은 분담).\\\\\\\\n\\\\\\\\n/** 가로쓰기 토큰 하나. w=0이라 centerX == x — 중점 계산을 정수로 유지한다. */\\\\\\\\nfunction h(str: string, x: number, y: number): TextItem {\\\\\\\\n  return { str, x, y, w: 0, h: 8 }\\\\\\\\n}\\\\\\\\n\\\\\\\\n/** 세로쓰기(rot=-90) 토큰 하나. verticalRuns가 단독 런으로 복원한다. */\\\\\\\\nfunction v(str: string, x: number, y: number): TextItem {\\\\\\\\n  return { str, x, y, w: 8, h: 0, rot: -90 }\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction page(items: TextItem[]): TextPage {\\\\\\\\n  return { widthPt: 1000, heightPt: 1000, items }\\\\\\\\n}\\\\\\\\n\\\\\\\\ndescribe('parseFramingPlan — 通り芯グリッド', () => {\\\\\\\\n  it('라벨이 하나도 없으면 通り芯ラベル未検出', () => {\\\\\\\\n    const parsed = parseFramingPlan(page([h('8700', 200, 80)]))\\\\\\\\n    expect(parsed.grids).toEqual([])\\\\\\\\n    expect(parsed.issues).toEqual(['通り芯ラベル未検出'])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('가로 밴드: 라벨 2본 + 중점 치수 → X 후보', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([h('X1', 100, 50), h('X2', 300, 50), h('6000', 200, 80)]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.issues).toEqual([])\\\\\\\\n    expect(parsed.grids).toEqual([\\\\\\\\n      {\\\\\\\\n        direction: 'X',\\\\\\\\n        axes: [\\\\\\\\n          { label: 'X1', positionPt: 100 },\\\\\\\\n          { label: 'X2', positionPt: 300 },\\\\\\\\n        ],\\\\\\\\n        spansMm: [6000],\\\\\\\\n        scalePtPerMm: 200 / 6000,\\\\\\\\n        totalConfirmed: false,\\\\\\\\n      },\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('세로 밴드: 위치는 y, 치수는 rot=-90 런에서 온다', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([h('bY1', 50, 100), h('bY2', 50, 300), v('4500', 80, 200)]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.issues).toEqual([])\\\\\\\\n    expect(parsed.grids).toEqual([\\\\\\\\n      {\\\\\\\\n        direction: 'Y',\\\\\\\\n        axes: [\\\\\\\\n          { label: 'bY1', positionPt: 100 },\\\\\\\\n          { label: 'bY2', positionPt: 300 },\\\\\\\\n        ],\\\\\\\\n        spansMm: [4500],\\\\\\\\n        scalePtPerMm: 200 / 4500,\\\\\\\\n        totalConfirmed: false,\\\\\\\\n      },\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('쉼표 치수(6,000)를 mm 정수로 읽는다', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([h('X1', 100, 50), h('X2', 300, 50), h('6,000', 200, 80)]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.grids[0]?.spansMm).toEqual([6000])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('인접 쌍의 중점에 치수가 없으면 寸法欠落 — 후보를 내지 않는다', () => {\\\\\\\\n    const cases: TextItem[][] = [\\\\\\\\n      // 치수 자체가 없다\\\\\\\\n      [h('X1', 100, 50), h('X2', 300, 50)],\\\\\\\\n      // 중점에서 20pt 벗어났다 (허용 15pt)\\\\\\\\n      [h('X1', 100, 50), h('X2', 300, 50), h('6000', 220, 80)],\\\\\\\\n      // 라벨 밴드에서 70pt 떨어진 다른 열의 숫자다 (창 60pt)\\\\\\\\n      [h('X1', 100, 50), h('X2', 300, 50), h('6000', 200, 120)],\\\\\\\\n    ]\\\\\\\\n    for (const items of cases) {\\\\\\\\n      const parsed = parseFramingPlan(page(items))\\\\\\\\n      expect(parsed.grids).toEqual([])\\\\\\\\n      expect(parsed.issues).toEqual(['寸法欠落'])\\\\\\\\n    }\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('스팬별 실측 축척이 3%를 넘게 갈리면 縮尺不整合', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([\\\\\\\\n        h('X1', 100, 50),\\\\\\\\n        h('X2', 300, 50),\\\\\\\\n        h('X3', 500, 50),\\\\\\\\n        h('6000', 200, 80),\\\\\\\\n        h('3000', 400, 80), // 같은 200pt인데 3000mm — 축척이 2배 갈린다\\\\\\\\n      ]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.grids).toEqual([])\\\\\\\\n    expect(parsed.issues).toEqual(['縮尺不整合'])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('전체 치수가 스팬 합과 일치하면 totalConfirmed', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([\\\\\\\\n        h('X1', 100, 50),\\\\\\\\n        h('X2', 300, 50),\\\\\\\\n        h('X3', 500, 50),\\\\\\\\n        h('6000', 200, 80),\\\\\\\\n        h('6000', 400, 80),\\\\\\\\n        h('12000', 300, 110), // 첫-끝 중점. 인접 중점(200·400)과는 100pt 떨어져 있다\\\\\\\\n      ]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.issues).toEqual([])\\\\\\\\n    expect(parsed.grids[0]?.totalConfirmed).toBe(true)\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('전체 치수가 스팬 합과 다르면 合計不一致 — 오독 신호이므로 후보를 내지 않는다', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([\\\\\\\\n        h('X1', 100, 50),\\\\\\\\n        h('X2', 300, 50),\\\\\\\\n        h('X3', 500, 50),\\\\\\\\n        h('6000', 200, 80),\\\\\\\\n        h('6000', 400, 80),\\\\\\\\n        h('11000', 300, 110),\\\\\\\\n      ]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.grids).toEqual([])\\\\\\\\n    expect(parsed.issues).toEqual(['合計不一致'])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('같은 밴드에서 라벨이 반복되면 블록 경계로 갈라 읽고, 동일 결과는 하나로 접는다', () => {\\\\\\\\n    // 한 페이지에 같은 그리드의 伏図가 두 블록 — 실물 p7의 배치다\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([\\\\\\\\n        h('X1', 100, 50),\\\\\\\\n        h('X2', 300, 50),\\\\\\\\n        h('X1', 700, 50),\\\\\\\\n        h('X2', 900, 50),\\\\\\\\n        h('6000', 200, 80),\\\\\\\\n        h('6000', 800, 80),\\\\\\\\n      ]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.issues).toEqual([])\\\\\\\\n    expect(parsed.grids).toHaveLength(1)\\\\\\\\n    expect(parsed.grids[0]?.axes.map((axis) => axis.label)).toEqual([\\\\\\\\n      'X1',\\\\\\\\n      'X2',\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('한 밴드에 X와 Y 라벨이 섞이면 ラベル文字混在 — 방향을 지어내지 않는다', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([h('X1', 50, 100), h('Y2', 50, 300), v('4500', 80, 200)]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.grids).toEqual([])\\\\\\\\n    expect(parsed.issues).toEqual(['ラベル文字混在'])\\\\\\\\n  })\\\\\\\\n})\\\\\\\\n\\\\\\\\ndescribe('parseFramingPlan — 부재 배치', () => {\\\\\\\\n  /** 3×3 격자 하나. X: X1·X2·X3 (0·200·400pt), Y: Y1·Y2·Y3 (0·200·400pt) */\\\\\\\\n  function gridItems(): TextItem[] {\\\\\\\\n    return [\\\\\\\\n      h('X1', 0, -40),\\\\\\\\n      h('X2', 200, -40),\\\\\\\\n      h('X3', 400, -40),\\\\\\\\n      h('6000', 100, -20),\\\\\\\\n      h('6000', 300, -20),\\\\\\\\n      h('Y1', -40, 0),\\\\\\\\n      h('Y2', -40, 200),\\\\\\\\n      h('Y3', -40, 400),\\\\\\\\n      v('6000', -20, 100),\\\\\\\\n      v('6000', -20, 300),\\\\\\\\n    ]\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  it('격자점 위의 부호는 格子点 — 방향을 갖지 않는다', () => {\\\\\\\\n    const parsed = parseFramingPlan(page([...gridItems(), h('C1', 200, 200)]))\\\\\\\\n    expect(parsed.blocks).toHaveLength(1)\\\\\\\\n    expect(parsed.blocks[0]?.placements).toEqual([\\\\\\\\n      { mark: 'C1', role: '格子点', ix: 1, iy: 1 },\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('X 중점·Y 격자점이면 辺 axis=X — 시작 격자점을 싣는다', () => {\\\\\\\\n    const parsed = parseFramingPlan(page([...gridItems(), h('G1', 300, 200)]))\\\\\\\\n    expect(parsed.blocks[0]?.placements).toEqual([\\\\\\\\n      { mark: 'G1', role: '辺', ix: 1, iy: 1, axis: 'X' },\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('X 격자점·Y 중점이면 辺 axis=Y', () => {\\\\\\\\n    const parsed = parseFramingPlan(page([...gridItems(), h('G2', 200, 100)]))\\\\\\\\n    expect(parsed.blocks[0]?.placements).toEqual([\\\\\\\\n      { mark: 'G2', role: '辺', ix: 1, iy: 0, axis: 'Y' },\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('양쪽 중점이면 ベイ — 원점 쪽 격자점을 싣는다', () => {\\\\\\\\n    const parsed = parseFramingPlan(page([...gridItems(), h('S1', 300, 300)]))\\\\\\\\n    expect(parsed.blocks[0]?.placements).toEqual([\\\\\\\\n      { mark: 'S1', role: 'ベイ', ix: 1, iy: 1 },\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('격자점에서도 중점에서도 먼 부호는 지어내지 않고 未配置로 남긴다', () => {\\\\\\\\n    // 허용은 **중앙값** 스팬의 1/4이므로, 등간격 격자에서는 어느 점이든 반드시\\\\\\\\n    // 어딘가에 붙는다(최대 거리가 정확히 허용과 같다). 못 붙는 자리는 유난히\\\\\\\\n    // 긴 스팬 안에서 생긴다 — 실물 yokohama의 1200mm 띠와 8700mm 스팬처럼\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([\\\\\\\\n        h('X1', 0, -40),\\\\\\\\n        h('X2', 200, -40),\\\\\\\\n        h('X3', 400, -40),\\\\\\\\n        h('X4', 1200, -40),\\\\\\\\n        h('6000', 100, -20),\\\\\\\\n        h('6000', 300, -20),\\\\\\\\n        h('24000', 800, -20),\\\\\\\\n        h('Y1', -40, 0),\\\\\\\\n        h('Y2', -40, 200),\\\\\\\\n        v('6000', -20, 100),\\\\\\\\n        // 격자점 400 에서도 중점 800 에서도 200pt — 중앙값 스팬 200 의 1/4 을 넘는다\\\\\\\\n        h('B1', 600, 0),\\\\\\\\n      ]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.blocks[0]?.placements).toEqual([])\\\\\\\\n    expect(parsed.blocks[0]?.unplacedMarks).toEqual(['B1'])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('블록 밖의 부호는 아예 보지 않는다 — 같은 페이지의 断面リスト가 섞이지 않는다', () => {\\\\\\\\n    const parsed = parseFramingPlan(page([...gridItems(), h('C9', 900, 900)]))\\\\\\\\n    expect(parsed.blocks[0]?.placements).toEqual([])\\\\\\\\n    expect(parsed.blocks[0]?.unplacedMarks).toEqual([])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('같은 부호가 여러 자리에 있으면 자리마다 하나씩 낸다', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([...gridItems(), h('C1', 0, 0), h('C1', 400, 400)]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.blocks[0]?.placements).toEqual([\\\\\\\\n      { mark: 'C1', role: '格子点', ix: 0, iy: 0 },\\\\\\\\n      { mark: 'C1', role: '格子点', ix: 2, iy: 2 },\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('伏図 제목을 원문 그대로 싣는다 — 階 대응은 사람이 정한다', () => {\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([...gridItems(), h('2階床伏図1/100', 200, 460)]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.blocks[0]?.title).toBe('2階床伏図1/100')\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('블록마다 자기 위치의 通り芯을 갖는다 — 그리드는 접혀도 블록은 안 접힌다', () => {\\\\\\\\n    const right = gridItems().map((item) => ({ ...item, x: item.x + 800 }))\\\\\\\\n    const parsed = parseFramingPlan(\\\\\\\\n      page([...gridItems(), ...right, h('C1', 200, 200), h('C2', 1000, 200)]),\\\\\\\\n    )\\\\\\\\n    expect(parsed.grids).toHaveLength(2)\\\\\\\\n    expect(parsed.blocks).toHaveLength(2)\\\\\\\\n    expect(parsed.blocks.map((block) => block.xAxes[0]?.positionPt)).toEqual([\\\\\\\\n      0, 800,\\\\\\\\n    ])\\\\\\\\n    expect(\\\\\\\\n      parsed.blocks.map((block) =>\\\\\\\\n        block.placements.map((placement) => placement.mark),\\\\\\\\n      ),\\\\\\\\n    ).toEqual([['C1'], ['C2']])\\\\\\\\n  })\\\\\\\\n})\\\\\\\\n\\\\\\\\r\\\\\\\\nimport { describe, expect, it } from 'vitest'\\\\\\\\n\\\\\\\\nimport type { Section } from '@/domain/model/member'\\\\\\\\nimport type { Project } from '@/domain/model/project'\\\\\\\\nimport { createSampleProject } from '@/domain/model/sample-project'\\\\\\\\n\\\\\\\\nimport { applyElevation, applyFramingPlan } from './apply'\\\\\\\\nimport type {\\\\\\\\n  ElevationCandidate,\\\\\\\\n  PlanBlock,\\\\\\\\n  PlanGridCandidate,\\\\\\\\n} from './types'\\\\\\\\n\\\\\\\\n// 断面은 손으로 짓지 않고 샘플 案件에서 빌린다 — 손으로 지으면 스키마가 자라날 때\\\\\\\\n// 이 테스트만 옛 모양으로 남고, 그 사실을 vitest는 알려주지 않는다 (tsc가 잡는다)\\\\\\\\nconst sample = createSampleProject()\\\\\\\\n\\\\\\\\nfunction sectionOf(kind: Section['kind'], mark: string): Section {\\\\\\\\n  const source = sample.sections.find((section) => section.kind === kind)\\\\\\\\n  if (!source) throw new Error(`sample has no ${kind} section`)\\\\\\\\n  return { ...source, id: `sec-${mark}`, mark }\\\\\\\\n}\\\\\\\\n\\\\\\\\nconst columnSection = (mark: string) => sectionOf('柱', mark)\\\\\\\\nconst girderSection = (mark: string) => sectionOf('大梁', mark)\\\\\\\\n\\\\\\\\nfunction project(overrides: Partial<Project> = {}): Project {\\\\\\\\n  return {\\\\\\\\n    schemaVersion: 11,\\\\\\\\n    name: 'test',\\\\\\\\n    grid: { xSpans: [6000], ySpans: [6000] },\\\\\\\\n    stories: [{ id: 'story-1', name: '1F', height: 4000 }],\\\\\\\\n    sections: [],\\\\\\\\n    members: [],\\\\\\\\n    ...overrides,\\\\\\\\n  }\\\\\\\\n}\\\\\\\\n\\\\\\\\nconst xGrid: PlanGridCandidate = {\\\\\\\\n  direction: 'X',\\\\\\\\n  axes: [\\\\\\\\n    { label: 'X1', positionPt: 0 },\\\\\\\\n    { label: 'X2', positionPt: 200 },\\\\\\\\n    { label: 'X3', positionPt: 400 },\\\\\\\\n  ],\\\\\\\\n  spansMm: [7000, 7000],\\\\\\\\n  scalePtPerMm: 200 / 7000,\\\\\\\\n  totalConfirmed: false,\\\\\\\\n}\\\\\\\\n\\\\\\\\nconst yGrid: PlanGridCandidate = {\\\\\\\\n  direction: 'Y',\\\\\\\\n  axes: [\\\\\\\\n    { label: 'Y1', positionPt: 0 },\\\\\\\\n    { label: 'Y2', positionPt: 200 },\\\\\\\\n  ],\\\\\\\\n  spansMm: [5000],\\\\\\\\n  scalePtPerMm: 200 / 5000,\\\\\\\\n  totalConfirmed: false,\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction block(overrides: Partial<PlanBlock> = {}): PlanBlock {\\\\\\\\n  return {\\\\\\\\n    xAxes: xGrid.axes,\\\\\\\\n    yAxes: yGrid.axes,\\\\\\\\n    placements: [],\\\\\\\\n    unplacedMarks: [],\\\\\\\\n    ...overrides,\\\\\\\\n  }\\\\\\\\n}\\\\\\\\n\\\\\\\\ndescribe('applyFramingPlan', () => {\\\\\\\\n  it('通り芯을 도면의 스팬으로 바꾼다', () => {\\\\\\\\n    const result = applyFramingPlan(project(), {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block(),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.project.grid).toEqual({\\\\\\\\n      xSpans: [7000, 7000],\\\\\\\\n      ySpans: [5000],\\\\\\\\n      xLabels: ['X1', 'X2', 'X3'],\\\\\\\\n      yLabels: ['Y1', 'Y2'],\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBeUndefined()\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('通り芯의 이름을 도면에서 읽은 원문 그대로 싣는다', () => {\\\\\\\\n    // 이것이 R13(端部 좌우 비대칭)의 선결 조건이다 — 이름이 있어야 도면의\\\\\\\\n    // 「Y3端／Y4端」을 런의 실제 방향과 맞출 수 있다\\\\\\\\n    const result = applyFramingPlan(project(), {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block(),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.project.grid.xLabels).toEqual(['X1', 'X2', 'X3'])\\\\\\\\n    expect(result.project.grid.yLabels).toEqual(['Y1', 'Y2'])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('이름만 다른 그리드는 「바뀌었다」로 보지 않는다', () => {\\\\\\\\n    // 라벨은 数量도 격자 index도 바꾸지 않는다 — 이름 때문에 다른 층을 버리라는\\\\\\\\n    // 물음이 뜨면 사용자는 이유를 알 수 없다\\\\\\\\n    const base = project({\\\\\\\\n      grid: { xSpans: [7000, 7000], ySpans: [5000] },\\\\\\\\n      sections: [columnSection('C1')],\\\\\\\\n      members: [\\\\\\\\n        {\\\\\\\\n          id: 'm1',\\\\\\\\n          kind: '柱',\\\\\\\\n          memberClass: '躯体',\\\\\\\\n          sectionId: 'sec-C1',\\\\\\\\n          storyId: 'story-2',\\\\\\\\n          position: { ix: 1, iy: 1 },\\\\\\\\n        },\\\\\\\\n      ],\\\\\\\\n      stories: [\\\\\\\\n        { id: 'story-1', name: '1F', height: 4000 },\\\\\\\\n        { id: 'story-2', name: '2F', height: 4000 },\\\\\\\\n      ],\\\\\\\\n    })\\\\\\\\n\\\\\\\\n    const result = applyFramingPlan(base, {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block(),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBeUndefined()\\\\\\\\n    expect(result.project.grid.xLabels).toEqual(['X1', 'X2', 'X3'])\\\\\\\\n    expect(result.project.members).toHaveLength(1)\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('다른 층에 부재가 있는데 通り芯이 바뀌면 통째로 거부한다', () => {\\\\\\\\n    // 격자 index는 스팬 배열에 매여 있다 — 스팬을 바꾸면 손대지 않은 층의\\\\\\\\n    // 부재가 조용히 다른 자리로 옮겨간다. 이 제품이 못 견디는 실패다\\\\\\\\n    const existing = project({\\\\\\\\n      sections: [columnSection('C1')],\\\\\\\\n      members: [\\\\\\\\n        {\\\\\\\\n          id: 'm1',\\\\\\\\n          kind: '柱',\\\\\\\\n          memberClass: '躯体',\\\\\\\\n          sectionId: 'sec-C1',\\\\\\\\n          storyId: 'story-2',\\\\\\\\n          position: { ix: 1, iy: 1 },\\\\\\\\n        },\\\\\\\\n      ],\\\\\\\\n      stories: [\\\\\\\\n        { id: 'story-1', name: '1F', height: 4000 },\\\\\\\\n        { id: 'story-2', name: '2F', height: 4000 },\\\\\\\\n      ],\\\\\\\\n    })\\\\\\\\n\\\\\\\\n    const result = applyFramingPlan(existing, {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block(),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBe('他階部材あり通り芯変更不可')\\\\\\\\n    expect(result.project).toBe(existing)\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('취입하는 층의 부재는 갈아 끼운다 — 두 번 눌러도 겹치지 않는다', () => {\\\\\\\\n    const base = project({ sections: [columnSection('C1')] })\\\\\\\\n    const options = {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block({\\\\\\\\n        placements: [{ mark: 'C1', role: '格子点' as const, ix: 1, iy: 1 }],\\\\\\\\n      }),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    const once = applyFramingPlan(base, options)\\\\\\\\n    const twice = applyFramingPlan(once.project, options)\\\\\\\\n    expect(once.project.members).toHaveLength(1)\\\\\\\\n    expect(twice.project.members).toHaveLength(1)\\\\\\\\n    expect(once.applied).toBe(1)\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('格子点의 柱를 ColumnPosition으로 넣는다', () => {\\\\\\\\n    const result = applyFramingPlan(project({ sections: [columnSection('C1')] }), {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block({\\\\\\\\n        placements: [{ mark: 'C1', role: '格子点', ix: 2, iy: 1 }],\\\\\\\\n      }),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.project.members).toEqual([\\\\\\\\n      {\\\\\\\\n        id: 'story-1-C1-2-1',\\\\\\\\n        kind: '柱',\\\\\\\\n        memberClass: '躯体',\\\\\\\\n        sectionId: 'sec-C1',\\\\\\\\n        storyId: 'story-1',\\\\\\\\n        position: { ix: 2, iy: 1 },\\\\\\\\n      },\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('辺의 大梁를 GirderPosition으로 넣는다 — axis를 그대로 옮긴다', () => {\\\\\\\\n    const result = applyFramingPlan(project({ sections: [girderSection('G1')] }), {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block({\\\\\\\\n        placements: [{ mark: 'G1', role: '辺', ix: 0, iy: 1, axis: 'X' }],\\\\\\\\n      }),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.project.members[0]?.position).toEqual({\\\\\\\\n      axis: 'X',\\\\\\\\n      ix: 0,\\\\\\\\n      iy: 1,\\\\\\\\n    })\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('断面一覧에 없는 符号은 넣지 않고 사유와 함께 남긴다', () => {\\\\\\\\n    const result = applyFramingPlan(project(), {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block({\\\\\\\\n        placements: [{ mark: 'C9', role: '格子点', ix: 0, iy: 0 }],\\\\\\\\n      }),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.project.members).toEqual([])\\\\\\\\n    expect(result.skipped).toEqual([{ mark: 'C9', reason: '断面未登録' }])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('種別과 자리가 어긋나면 넣지 않는다 — 柱를 辺에 놓지 않는다', () => {\\\\\\\\n    const result = applyFramingPlan(project({ sections: [columnSection('C1')] }), {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block({\\\\\\\\n        placements: [{ mark: 'C1', role: '辺', ix: 0, iy: 0, axis: 'X' }],\\\\\\\\n      }),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.project.members).toEqual([])\\\\\\\\n    expect(result.skipped).toEqual([{ mark: 'C1', reason: '部材種別相違' }])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('격자 밖을 가리키는 배치는 넣지 않는다', () => {\\\\\\\\n    // 도면의 通り芯 수와 취입하는 그리드가 어긋난 경우 — 지어내지 않는다\\\\\\\\n    const result = applyFramingPlan(project({ sections: [columnSection('C1')] }), {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block({\\\\\\\\n        placements: [{ mark: 'C1', role: '格子点', ix: 3, iy: 0 }],\\\\\\\\n      }),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.project.members).toEqual([])\\\\\\\\n    expect(result.skipped).toEqual([{ mark: 'C1', reason: '格子外' }])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('없는 층을 가리키면 통째로 거부한다', () => {\\\\\\\\n    const base = project()\\\\\\\\n    const result = applyFramingPlan(base, {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block(),\\\\\\\\n      storyId: 'story-9',\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBe('階未指定')\\\\\\\\n    expect(result.project).toBe(base)\\\\\\\\n  })\\\\\\\\n})\\\\\\\\n\\\\\\\\ndescribe('applyFramingPlan — 다른 층을 버리는 동의', () => {\\\\\\\\n  const existing = () =>\\\\\\\\n    project({\\\\\\\\n      sections: [columnSection('C1')],\\\\\\\\n      members: [\\\\\\\\n        {\\\\\\\\n          id: 'm1',\\\\\\\\n          kind: '柱',\\\\\\\\n          memberClass: '躯体',\\\\\\\\n          sectionId: 'sec-C1',\\\\\\\\n          storyId: 'story-2',\\\\\\\\n          position: { ix: 1, iy: 1 },\\\\\\\\n        },\\\\\\\\n      ],\\\\\\\\n      stories: [\\\\\\\\n        { id: 'story-1', name: '1F', height: 4000 },\\\\\\\\n        { id: 'story-2', name: '2F', height: 4000 },\\\\\\\\n      ],\\\\\\\\n    })\\\\\\\\n\\\\\\\\n  it('동의하면 다른 층 부재를 남기지 않고 통째로 버린다', () => {\\\\\\\\n    const result = applyFramingPlan(existing(), {\\\\\\\\n      xGrid,\\\\\\\\n      yGrid,\\\\\\\\n      block: block({\\\\\\\\n        placements: [{ mark: 'C1', role: '格子点', ix: 1, iy: 1 }],\\\\\\\\n      }),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n      discardOtherStories: true,\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBeUndefined()\\\\\\\\n    // 반쯤 옮겨 놓느니 비운다 — 남기면 index가 다른 자리를 가리킨다\\\\\\\\n    expect(result.project.members.map((member) => member.storyId)).toEqual([\\\\\\\\n      'story-1',\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('通り芯이 그대로면 동의 없이도 다른 층을 건드리지 않는다', () => {\\\\\\\\n    const base = existing()\\\\\\\\n    const result = applyFramingPlan(base, {\\\\\\\\n      xGrid: { ...xGrid, spansMm: base.grid.xSpans },\\\\\\\\n      yGrid: { ...yGrid, spansMm: base.grid.ySpans },\\\\\\\\n      block: block(),\\\\\\\\n      storyId: 'story-1',\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBeUndefined()\\\\\\\\n    expect(result.project.members).toHaveLength(1)\\\\\\\\n  })\\\\\\\\n})\\\\\\\\n\\\\\\\\ndescribe('applyElevation', () => {\\\\\\\\n  // 도면 순서는 위에서 아래다. 실물 yokohama p8이 이 모양이다 —\\\\\\\\n  // 맨 위는 라벨이 없는 パラペット 천단이고, 그 아래로 RCL·2FL·1FL·基礎下端이다.\\\\\\\\n  const candidate: ElevationCandidate = {\\\\\\\\n    titles: ['bY1通り軸組図1/100'],\\\\\\\\n    levels: [\\\\\\\\n      { labels: [], positionPt: 159 },\\\\\\\\n      { labels: ['中央棟RCL(水下)'], positionPt: 199 },\\\\\\\\n      { labels: ['2FL'], positionPt: 315 },\\\\\\\\n      { labels: ['中央棟1FL', '基準GL'], positionPt: 442 },\\\\\\\\n      { labels: ['基礎下端'], positionPt: 518 },\\\\\\\\n    ],\\\\\\\\n    heightsMm: [1400, 4100, 4480, 2690],\\\\\\\\n    scalePtPerMm: 0.02835,\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  it('고른 범위의 간격만 階가 되고, 아래에서 위로 쌓인다', () => {\\\\\\\\n    // 1FL(3)에서 RCL(1)까지 → 1階(4480)와 2階(4100). パラペット(1400)와\\\\\\\\n    // 基礎(2690)는 階가 아니므로 범위 밖이다\\\\\\\\n    const result = applyElevation(project(), {\\\\\\\\n      candidate,\\\\\\\\n      topLevelIndex: 1,\\\\\\\\n      bottomLevelIndex: 3,\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBeUndefined()\\\\\\\\n    expect(result.project.stories.map((story) => story.height)).toEqual([\\\\\\\\n      4480, 4100,\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('階의 이름은 그 階의 바닥이 되는 레벨의 원문이다', () => {\\\\\\\\n    const result = applyElevation(project(), {\\\\\\\\n      candidate,\\\\\\\\n      topLevelIndex: 1,\\\\\\\\n      bottomLevelIndex: 3,\\\\\\\\n    })\\\\\\\\n    // 같은 높이에 라벨이 둘이면 둘 다 남긴다 — 하나를 고르지 않는다\\\\\\\\n    expect(result.project.stories.map((story) => story.name)).toEqual([\\\\\\\\n      '中央棟1FL／基準GL',\\\\\\\\n      '2FL',\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('라벨이 없는 레벨이 바닥이면 이름을 지어내지 않고 번호로 둔다', () => {\\\\\\\\n    const result = applyElevation(project(), {\\\\\\\\n      candidate,\\\\\\\\n      topLevelIndex: 0,\\\\\\\\n      bottomLevelIndex: 1,\\\\\\\\n    })\\\\\\\\n    expect(result.project.stories.map((story) => story.name)).toEqual([\\\\\\\\n      '中央棟RCL(水下)',\\\\\\\\n    ])\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('범위가 한 칸도 없으면 거부한다', () => {\\\\\\\\n    const base = project()\\\\\\\\n    const result = applyElevation(base, {\\\\\\\\n      candidate,\\\\\\\\n      topLevelIndex: 2,\\\\\\\\n      bottomLevelIndex: 2,\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBe('階範囲不正')\\\\\\\\n    expect(result.project).toBe(base)\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('부재가 있으면 통째로 거부한다 — 階를 갈면 부재가 갈 곳을 잃는다', () => {\\\\\\\\n    const base = project({\\\\\\\\n      sections: [columnSection('C1')],\\\\\\\\n      members: [\\\\\\\\n        {\\\\\\\\n          id: 'm1',\\\\\\\\n          kind: '柱',\\\\\\\\n          memberClass: '躯体',\\\\\\\\n          sectionId: 'sec-C1',\\\\\\\\n          storyId: 'story-1',\\\\\\\\n          position: { ix: 0, iy: 0 },\\\\\\\\n        },\\\\\\\\n      ],\\\\\\\\n    })\\\\\\\\n    const result = applyElevation(base, {\\\\\\\\n      candidate,\\\\\\\\n      topLevelIndex: 1,\\\\\\\\n      bottomLevelIndex: 3,\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBe('部材あり階置換不可')\\\\\\\\n    expect(result.project).toBe(base)\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('동의하면 부재를 버리고 階를 갈아 끼운다', () => {\\\\\\\\n    const base = project({\\\\\\\\n      sections: [columnSection('C1')],\\\\\\\\n      members: [\\\\\\\\n        {\\\\\\\\n          id: 'm1',\\\\\\\\n          kind: '柱',\\\\\\\\n          memberClass: '躯体',\\\\\\\\n          sectionId: 'sec-C1',\\\\\\\\n          storyId: 'story-1',\\\\\\\\n          position: { ix: 0, iy: 0 },\\\\\\\\n        },\\\\\\\\n      ],\\\\\\\\n    })\\\\\\\\n    const result = applyElevation(base, {\\\\\\\\n      candidate,\\\\\\\\n      topLevelIndex: 1,\\\\\\\\n      bottomLevelIndex: 3,\\\\\\\\n      discardMembers: true,\\\\\\\\n    })\\\\\\\\n    expect(result.refusal).toBeUndefined()\\\\\\\\n    expect(result.project.members).toEqual([])\\\\\\\\n    expect(result.project.stories).toHaveLength(2)\\\\\\\\n  })\\\\\\\\n})\\\\\\\\n\\\\\\\\r\\\\\\\\n'use client'\\\\\\\\n\\\\\\\\nimport { useMemo, useRef, useState, type ChangeEvent } from 'react'\\\\\\\\n\\\\\\\\nimport {\\\\\\\\n  applyElevation,\\\\\\\\n  applyFramingPlan,\\\\\\\\n  type ElevationApplyResult,\\\\\\\\n  type PlanApplyResult,\\\\\\\\n} from '@/lib/import/framing-plan/apply'\\\\\\\\nimport { parseFrameElevations } from '@/lib/import/framing-plan/elevation'\\\\\\\\nimport { parseFramingPlan } from '@/lib/import/framing-plan/parse'\\\\\\\\nimport type {\\\\\\\\n  ElevationCandidate,\\\\\\\\n  PlanBlock,\\\\\\\\n  PlanGridCandidate,\\\\\\\\n} from '@/lib/import/framing-plan/types'\\\\\\\\nimport { extractTextPages } from '@/lib/import/pdf-text'\\\\\\\\nimport type { TextPage } from '@/lib/import/section-list/types'\\\\\\\\nimport { useAppStore } from '@/lib/store'\\\\\\\\nimport { t } from '@/lib/i18n'\\\\\\\\n\\\\\\\\nimport styles from './PlanImport.module.css'\\\\\\\\n\\\\\\\\n/**\\\\\\\\n * 伏図·軸組図에서 읽은 형상을 **후보로** 보여주고, 사용자가 승인하면 案件에\\\\\\\\n * 넣는다 (ADR-030). 断面リスト 취입(ADR-018)과 같은 규약이다 — 승인 전에는\\\\\\\\n * 형상이 되지 않고, 못 읽은 것은 지어내지 않고 사유를 말한다.\\\\\\\\n *\\\\\\\\n * 간이 평면 에디터를 대체하지 않는다. 래스터 도면·미지 형식에서는 이 화면이\\\\\\\\n * 빈 후보로 정직하게 실패하고, 그때 형상을 넣는 길은 손입력뿐이다 (ADR-004).\\\\\\\\n */\\\\\\\\n\\\\\\\\ninterface PlanImportProps {\\\\\\\\n  /** 테스트에서 PDF 추출을 건너뛰고 페이지를 직접 넣는다 */\\\\\\\\n  initialPages?: TextPage[]\\\\\\\\n  extractPages?: (file: File) => Promise<TextPage[]>\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction Axes({\\\\\\\\n  candidate,\\\\\\\\n  label,\\\\\\\\n}: {\\\\\\\\n  candidate: PlanGridCandidate\\\\\\\\n  label: string\\\\\\\\n}) {\\\\\\\\n  return (\\\\\\\\n    <div className={styles.group} data-testid={`plan-import-grid-${candidate.direction}`}>\\\\\\\\n      <h4 className={styles.groupTitle}>{label}</h4>\\\\\\\\n      <p className={styles.axes}>\\\\\\\\n        {candidate.axes.map((axis, index) => (\\\\\\\\n          <span key={`${axis.label}-${index}`}>\\\\\\\\n            <span className={styles.axis}>{axis.label}</span>\\\\\\\\n            {index < candidate.spansMm.length ? (\\\\\\\\n              <span className={styles.span}>\\\\\\\\n                {` — ${candidate.spansMm[index]} — `}\\\\\\\\n              </span>\\\\\\\\n            ) : null}\\\\\\\\n          </span>\\\\\\\\n        ))}\\\\\\\\n      </p>\\\\\\\\n    </div>\\\\\\\\n  )\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction Elevation({\\\\\\\\n  candidate,\\\\\\\\n  index,\\\\\\\\n  locale,\\\\\\\\n  onApply,\\\\\\\\n  result,\\\\\\\\n  discardMembers,\\\\\\\\n  onDiscardMembersChange,\\\\\\\\n}: {\\\\\\\\n  candidate: ElevationCandidate\\\\\\\\n  index: number\\\\\\\\n  locale: 'ja' | 'ko'\\\\\\\\n  onApply: (topLevelIndex: number, bottomLevelIndex: number) => void\\\\\\\\n  result: ElevationApplyResult | null\\\\\\\\n  discardMembers: boolean\\\\\\\\n  onDiscardMembersChange: (next: boolean) => void\\\\\\\\n}) {\\\\\\\\n  // 「어느 레벨이 階의 경계인가」는 조문이 아니라 설계 의도라 사람이 고른다\\\\\\\\n  // (ADR-030). 기본값은 양 끝 — 제품은 パラペット이나 基礎를 알아볼 수 없으므로\\\\\\\\n  // 가장 넓게 잡아 두고 사용자가 좁힌다\\\\\\\\n  const [top, setTop] = useState(0)\\\\\\\\n  const [bottom, setBottom] = useState(candidate.levels.length - 1)\\\\\\\\n\\\\\\\\n  const levelLabel = (levelIndex: number) => {\\\\\\\\n    const level = candidate.levels[levelIndex]\\\\\\\\n    return level.labels.length > 0\\\\\\\\n      ? level.labels.join('／')\\\\\\\\n      : t(locale, 'planImport.levelUnlabelled')\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return (\\\\\\\\n    <div\\\\\\\\n      className={styles.elevation}\\\\\\\\n      data-testid={`plan-import-elevation-${index}`}\\\\\\\\n    >\\\\\\\\n      <div className={styles.blockHeading}>\\\\\\\\n        <strong>\\\\\\\\n          {candidate.titles.join('・') ||\\\\\\\\n            t(locale, 'planImport.elevationUntitled')}\\\\\\\\n        </strong>\\\\\\\\n        <button\\\\\\\\n          type=\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\"\\\\\\\\n          className={styles.applyButton}\\\\\\\\n          data-testid={`plan-import-apply-elevation-${index}`}\\\\\\\\n          onClick={() => onApply(top, bottom)}\\\\\\\\n        >\\\\\\\\n          {t(locale, 'planImport.applyStories')}\\\\\\\\n        </button>\\\\\\\\n      </div>\\\\\\\\n      <p className={styles.axes}>\\\\\\\\n        {candidate.levels.map((level, levelIndex) => (\\\\\\\\n          <span key={levelIndex}>\\\\\\\\n            <span className={styles.axis}>\\\\\\\\n              {level.labels.join('／') || '—'}\\\\\\\\n            </span>\\\\\\\\n            {levelIndex < candidate.heightsMm.length ? (\\\\\\\\n              <span className={styles.span}>\\\\\\\\n                {` — ${candidate.heightsMm[levelIndex]} — `}\\\\\\\\n              </span>\\\\\\\\n            ) : null}\\\\\\\\n          </span>\\\\\\\\n        ))}\\\\\\\\n      </p>\\\\\\\\n      <div className={styles.storyPicker}>\\\\\\\\n        <label className={styles.storyPicker}>\\\\\\\\n          {t(locale, 'planImport.topLevel')}\\\\\\\\n          <select\\\\\\\\n            data-testid={`plan-import-level-top-${index}`}\\\\\\\\n            value={top}\\\\\\\\n            onChange={(event) => setTop(Number(event.target.value))}\\\\\\\\n          >\\\\\\\\n            {candidate.levels.map((level, levelIndex) => (\\\\\\\\n              <option key={levelIndex} value={levelIndex}>\\\\\\\\n                {levelLabel(levelIndex)}\\\\\\\\n              </option>\\\\\\\\n            ))}\\\\\\\\n          </select>\\\\\\\\n        </label>\\\\\\\\n        <label className={styles.storyPicker}>\\\\\\\\n          {t(locale, 'planImport.bottomLevel')}\\\\\\\\n          <select\\\\\\\\n            data-testid={`plan-import-level-bottom-${index}`}\\\\\\\\n            value={bottom}\\\\\\\\n            onChange={(event) => setBottom(Number(event.target.value))}\\\\\\\\n          >\\\\\\\\n            {candidate.levels.map((level, levelIndex) => (\\\\\\\\n              <option key={levelIndex} value={levelIndex}>\\\\\\\\n                {levelLabel(levelIndex)}\\\\\\\\n              </option>\\\\\\\\n            ))}\\\\\\\\n          </select>\\\\\\\\n        </label>\\\\\\\\n      </div>\\\\\\\\n      {/* 동의는 거부를 한 번 본 뒤에만 물어본다 */}\\\\\\\\n      {result?.refusal === '部材あり階置換不可' ? (\\\\\\\\n        <label className={styles.storyPicker}>\\\\\\\\n          <input\\\\\\\\n            type=\\\\\\\\\\\\\\\"checkbox\\\\\\\\\\\\\\\"\\\\\\\\n            data-testid={`plan-import-discard-members-${index}`}\\\\\\\\n            checked={discardMembers}\\\\\\\\n            onChange={(event) => onDiscardMembersChange(event.target.checked)}\\\\\\\\n          />\\\\\\\\n          {t(locale, 'planImport.discardMembers')}\\\\\\\\n        </label>\\\\\\\\n      ) : null}\\\\\\\\n      {result ? (\\\\\\\\n        <p\\\\\\\\n          className={styles.muted}\\\\\\\\n          data-testid={`plan-import-elevation-result-${index}`}\\\\\\\\n        >\\\\\\\\n          {result.refusal\\\\\\\\n            ? t(locale, `planImport.elevationRefusal.${result.refusal}`)\\\\\\\\n            : `${t(locale, 'planImport.appliedStories')}: ${result.applied}`}\\\\\\\\n        </p>\\\\\\\\n      ) : null}\\\\\\\\n    </div>\\\\\\\\n  )\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport function PlanImport({\\\\\\\\n  initialPages,\\\\\\\\n  extractPages = extractTextPages,\\\\\\\\n}: PlanImportProps) {\\\\\\\\n  const locale = useAppStore(({ locale }) => locale)\\\\\\\\n  const stories = useAppStore(({ project }) => project.stories)\\\\\\\\n  const updateProject = useAppStore(({ updateProject }) => updateProject)\\\\\\\\n  const inputRef = useRef<HTMLInputElement>(null)\\\\\\\\n  const [pages, setPages] = useState<TextPage[] | null>(initialPages ?? null)\\\\\\\\n  const [open, setOpen] = useState(initialPages !== undefined)\\\\\\\\n  const [loading, setLoading] = useState(false)\\\\\\\\n  const [failed, setFailed] = useState(false)\\\\\\\\n  const [storyId, setStoryId] = useState<string>(stories[0]?.id ?? '')\\\\\\\\n  const [result, setResult] = useState<PlanApplyResult | null>(null)\\\\\\\\n  const [discardOtherStories, setDiscardOtherStories] = useState(false)\\\\\\\\n  const [discardMembers, setDiscardMembers] = useState(false)\\\\\\\\n  const [elevationResults, setElevationResults] = useState<\\\\\\\\n    Record<number, ElevationApplyResult>\\\\\\\\n  >({})\\\\\\\\n  // 연속 선택 시 늦게 끝난 이전 파일의 결과가 최신 결과를 덮지 않게 한다\\\\\\\\n  const requestRef = useRef(0)\\\\\\\\n\\\\\\\\n  const plans = useMemo(\\\\\\\\n    () => (pages ?? []).map((page) => parseFramingPlan(page)),\\\\\\\\n    [pages],\\\\\\\\n  )\\\\\\\\n  const elevations = useMemo(\\\\\\\\n    () => (pages ?? []).flatMap((page) => parseFrameElevations(page).elevations),\\\\\\\\n    [pages],\\\\\\\\n  )\\\\\\\\n  const grids = plans.flatMap((plan) => plan.grids)\\\\\\\\n  const xGrid = grids.find((grid) => grid.direction === 'X')\\\\\\\\n  const yGrid = grids.find((grid) => grid.direction === 'Y')\\\\\\\\n  const blocks: PlanBlock[] = plans.flatMap((plan) => plan.blocks)\\\\\\\\n  // 사유는 페이지마다 나오므로 접는다 — 같은 말이 페이지 수만큼 늘어서면 읽히지 않는다\\\\\\\\n  const issues = [...new Set(plans.flatMap((plan) => plan.issues))]\\\\\\\\n\\\\\\\\n  const selectFile = async (event: ChangeEvent<HTMLInputElement>) => {\\\\\\\\n    const input = event.currentTarget\\\\\\\\n    const file = input.files?.[0]\\\\\\\\n    if (!file) return\\\\\\\\n\\\\\\\\n    const requestId = ++requestRef.current\\\\\\\\n    setOpen(true)\\\\\\\\n    setLoading(true)\\\\\\\\n    setFailed(false)\\\\\\\\n    setResult(null)\\\\\\\\n    setElevationResults({})\\\\\\\\n    try {\\\\\\\\n      const next = await extractPages(file)\\\\\\\\n      if (requestRef.current !== requestId) return\\\\\\\\n      setPages(next)\\\\\\\\n    } catch {\\\\\\\\n      if (requestRef.current !== requestId) return\\\\\\\\n      setPages(null)\\\\\\\\n      setFailed(true)\\\\\\\\n    } finally {\\\\\\\\n      if (requestRef.current === requestId) setLoading(false)\\\\\\\\n      input.value = ''\\\\\\\\n    }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  const apply = (block: PlanBlock) => {\\\\\\\\n    if (!xGrid || !yGrid) return\\\\\\\\n    let applied: PlanApplyResult | undefined\\\\\\\\n    updateProject((project) => {\\\\\\\\n      applied = applyFramingPlan(project, {\\\\\\\\n        xGrid,\\\\\\\\n        yGrid,\\\\\\\\n        block,\\\\\\\\n        storyId,\\\\\\\\n        discardOtherStories,\\\\\\\\n      })\\\\\\\\n      return applied.project\\\\\\\\n    })\\\\\\\\n    if (applied) setResult(applied)\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  const applyStories = (\\\\\\\\n    candidate: ElevationCandidate,\\\\\\\\n    index: number,\\\\\\\\n    topLevelIndex: number,\\\\\\\\n    bottomLevelIndex: number,\\\\\\\\n  ) => {\\\\\\\\n    let applied: ElevationApplyResult | undefined\\\\\\\\n    updateProject((project) => {\\\\\\\\n      applied = applyElevation(project, {\\\\\\\\n        candidate,\\\\\\\\n        topLevelIndex,\\\\\\\\n        bottomLevelIndex,\\\\\\\\n        discardMembers,\\\\\\\\n      })\\\\\\\\n      return applied.project\\\\\\\\n    })\\\\\\\\n    if (applied) {\\\\\\\\n      const next = applied\\\\\\\\n      setElevationResults((current) => ({ ...current, [index]: next }))\\\\\\\\n    }\\\\\\\\n  }\\\\\\\\n\\\\\\\\n  return (\\\\\\\\n    <div className={styles.control}>\\\\\\\\n      <button\\\\\\\\n        type=\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\"\\\\\\\\n        className={styles.openButton}\\\\\\\\n        onClick={() => {\\\\\\\\n          if (pages) setOpen(true)\\\\\\\\n          else inputRef.current?.click()\\\\\\\\n        }}\\\\\\\\n      >\\\\\\\\n        {t(locale, 'planImport.open')}\\\\\\\\n      </button>\\\\\\\\n      <input\\\\\\\\n        ref={inputRef}\\\\\\\\n        className={styles.fileInput}\\\\\\\\n        data-testid=\\\\\\\\\\\\\\\"plan-import-file\\\\\\\\\\\\\\\"\\\\\\\\n        type=\\\\\\\\\\\\\\\"file\\\\\\\\\\\\\\\"\\\\\\\\n        accept=\\\\\\\\\\\\\\\"application/pdf\\\\\\\\\\\\\\\"\\\\\\\\n        aria-label={t(locale, 'planImport.file')}\\\\\\\\n        onChange={(event) => void selectFile(event)}\\\\\\\\n      />\\\\\\\\n      {open ? (\\\\\\\\n        <section\\\\\\\\n          className={styles.panel}\\\\\\\\n          role=\\\\\\\\\\\\\\\"dialog\\\\\\\\\\\\\\\"\\\\\\\\n          aria-modal=\\\\\\\\\\\\\\\"false\\\\\\\\\\\\\\\"\\\\\\\\n          aria-labelledby=\\\\\\\\\\\\\\\"plan-import-title\\\\\\\\\\\\\\\"\\\\\\\\n        >\\\\\\\\n          <header className={styles.panelHeader}>\\\\\\\\n            <h3 id=\\\\\\\\\\\\\\\"plan-import-title\\\\\\\\\\\\\\\">{t(locale, 'planImport.title')}</h3>\\\\\\\\n            <div className={styles.panelActions}>\\\\\\\\n              <button\\\\\\\\n                type=\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\"\\\\\\\\n                className={styles.chooseButton}\\\\\\\\n                onClick={() => inputRef.current?.click()}\\\\\\\\n              >\\\\\\\\n                {t(locale, 'planImport.chooseAnother')}\\\\\\\\n              </button>\\\\\\\\n              <button\\\\\\\\n                type=\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\"\\\\\\\\n                className={styles.closeButton}\\\\\\\\n                onClick={() => setOpen(false)}\\\\\\\\n              >\\\\\\\\n                {t(locale, 'planImport.close')}\\\\\\\\n              </button>\\\\\\\\n            </div>\\\\\\\\n          </header>\\\\\\\\n          <div className={styles.panelBody}>\\\\\\\\n            {loading ? (\\\\\\\\n              <p role=\\\\\\\\\\\\\\\"status\\\\\\\\\\\\\\\">{t(locale, 'planImport.loading')}</p>\\\\\\\\n            ) : failed ? (\\\\\\\\n              <p role=\\\\\\\\\\\\\\\"alert\\\\\\\\\\\\\\\">{t(locale, 'planImport.error')}</p>\\\\\\\\n            ) : (\\\\\\\\n              <>\\\\\\\\n                {issues.length > 0 ? (\\\\\\\\n                  <ul className={styles.issues} data-testid=\\\\\\\\\\\\\\\"plan-import-issues\\\\\\\\\\\\\\\">\\\\\\\\n                    {issues.map((issue) => (\\\\\\\\n                      <li key={issue}>\\\\\\\\n                        {t(locale, `planImport.issue.${issue}`)}\\\\\\\\n                      </li>\\\\\\\\n                    ))}\\\\\\\\n                  </ul>\\\\\\\\n                ) : null}\\\\\\\\n\\\\\\\\n                {xGrid ? (\\\\\\\\n                  <Axes candidate={xGrid} label={t(locale, 'planImport.gridX')} />\\\\\\\\n                ) : null}\\\\\\\\n                {yGrid ? (\\\\\\\\n                  <Axes candidate={yGrid} label={t(locale, 'planImport.gridY')} />\\\\\\\\n                ) : null}\\\\\\\\n\\\\\\\\n                {blocks.length > 0 ? (\\\\\\\\n                  <label className={styles.storyPicker}>\\\\\\\\n                    {t(locale, 'planImport.story')}\\\\\\\\n                    <select\\\\\\\\n                      data-testid=\\\\\\\\\\\\\\\"plan-import-story\\\\\\\\\\\\\\\"\\\\\\\\n                      value={storyId}\\\\\\\\n                      onChange={(event) => setStoryId(event.target.value)}\\\\\\\\n                    >\\\\\\\\n                      {stories.map((story) => (\\\\\\\\n                        <option key={story.id} value={story.id}>\\\\\\\\n                          {story.name}\\\\\\\\n                        </option>\\\\\\\\n                      ))}\\\\\\\\n                    </select>\\\\\\\\n                  </label>\\\\\\\\n                ) : null}\\\\\\\\n\\\\\\\\n                {blocks.map((block, index) => (\\\\\\\\n                  <div\\\\\\\\n                    key={`${block.title ?? 'block'}-${index}`}\\\\\\\\n                    className={styles.block}\\\\\\\\n                  >\\\\\\\\n                    <div className={styles.blockHeading}>\\\\\\\\n                      <strong>\\\\\\\\n                        {block.title ?? t(locale, 'planImport.blockUntitled')}\\\\\\\\n                      </strong>\\\\\\\\n                      <button\\\\\\\\n                        type=\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\"\\\\\\\\n                        className={styles.applyButton}\\\\\\\\n                        data-testid={`plan-import-apply-${index}`}\\\\\\\\n                        onClick={() => apply(block)}\\\\\\\\n                      >\\\\\\\\n                        {t(locale, 'planImport.apply')}\\\\\\\\n                      </button>\\\\\\\\n                    </div>\\\\\\\\n                    <p className={styles.muted}>\\\\\\\\n                      {`${t(locale, 'planImport.placements')}: ${block.placements.length}`}\\\\\\\\n                      {block.unplacedMarks.length > 0\\\\\\\\n                        ? ` / ${t(locale, 'planImport.unplaced')}: ${block.unplacedMarks.join('・')}`\\\\\\\\n                        : ''}\\\\\\\\n                    </p>\\\\\\\\n                  </div>\\\\\\\\n                ))}\\\\\\\\n\\\\\\\\n                {elevations.map((candidate, index) => (\\\\\\\\n                  <Elevation\\\\\\\\n                    key={index}\\\\\\\\n                    candidate={candidate}\\\\\\\\n                    index={index}\\\\\\\\n                    locale={locale}\\\\\\\\n                    result={elevationResults[index] ?? null}\\\\\\\\n                    discardMembers={discardMembers}\\\\\\\\n                    onDiscardMembersChange={setDiscardMembers}\\\\\\\\n                    onApply={(topLevel, bottomLevel) =>\\\\\\\\n                      applyStories(candidate, index, topLevel, bottomLevel)\\\\\\\\n                    }\\\\\\\\n                  />\\\\\\\\n                ))}\\\\\\\\n\\\\\\\\n                {/* 동의는 거부를 한 번 본 뒤에만 물어본다 — 처음부터 내놓으면\\\\\\\\n                    「무슨 뜻인지 모른 채 켜 두는 칸」이 된다 */}\\\\\\\\n                {result?.refusal === '他階部材あり通り芯変更不可' ? (\\\\\\\\n                  <label className={styles.storyPicker}>\\\\\\\\n                    <input\\\\\\\\n                      type=\\\\\\\\\\\\\\\"checkbox\\\\\\\\\\\\\\\"\\\\\\\\n                      data-testid=\\\\\\\\\\\\\\\"plan-import-discard\\\\\\\\\\\\\\\"\\\\\\\\n                      checked={discardOtherStories}\\\\\\\\n                      onChange={(event) =>\\\\\\\\n                        setDiscardOtherStories(event.target.checked)\\\\\\\\n                      }\\\\\\\\n                    />\\\\\\\\n                    {t(locale, 'planImport.discardOtherStories')}\\\\\\\\n                  </label>\\\\\\\\n                ) : null}\\\\\\\\n\\\\\\\\n                {result ? (\\\\\\\\n                  <p className={styles.muted} data-testid=\\\\\\\\\\\\\\\"plan-import-result\\\\\\\\\\\\\\\">\\\\\\\\n                    {result.refusal\\\\\\\\n                      ? t(locale, `planImport.refusal.${result.refusal}`)\\\\\\\\n                      : `${t(locale, 'planImport.applied')}: ${result.applied}`}\\\\\\\\n                    {result.skipped.length > 0\\\\\\\\n                      ? ` / ${result.skipped\\\\\\\\n                          .map(\\\\\\\\n                            ({ mark, reason }) =>\\\\\\\\n                              `${mark}(${t(locale, `planImport.skip.${reason}`)})`,\\\\\\\\n                          )\\\\\\\\n                          .join('、')}`\\\\\\\\n                      : ''}\\\\\\\\n                  </p>\\\\\\\\n                ) : null}\\\\\\\\n              </>\\\\\\\\n            )}\\\\\\\\n          </div>\\\\\\\\n        </section>\\\\\\\\n      ) : null}\\\\\\\\n    </div>\\\\\\\\n  )\\\\\\\\n}\\\\\\\\n\\\\\\\\r\\\\\\\\nimport { act, fireEvent, render, screen, waitFor } from '@testing-library/react'\\\\\\\\nimport { beforeEach, describe, expect, it, vi } from 'vitest'\\\\\\\\n\\\\\\\\nimport { createSampleProject } from '@/domain/model/sample-project'\\\\\\\\nimport type { TextPage } from '@/lib/import/section-list/types'\\\\\\\\nimport { useAppStore } from '@/lib/store'\\\\\\\\n\\\\\\\\nimport planFixture from '../../../tests/fixtures/section-import/textitems/yokohama-p7.json'\\\\\\\\nimport elevationFixture from '../../../tests/fixtures/section-import/textitems/yokohama-p8.json'\\\\\\\\n\\\\\\\\nimport { PlanImport } from './PlanImport'\\\\\\\\n\\\\\\\\nconst planPage: TextPage = { ...planFixture.page, items: planFixture.items }\\\\\\\\nconst elevationPage: TextPage = {\\\\\\\\n  ...elevationFixture.page,\\\\\\\\n  items: elevationFixture.items,\\\\\\\\n}\\\\\\\\n\\\\\\\\nbeforeEach(() => {\\\\\\\\n  act(() => {\\\\\\\\n    useAppStore.setState({ project: createSampleProject() })\\\\\\\\n  })\\\\\\\\n})\\\\\\\\n\\\\\\\\nfunction open(pages: TextPage[]) {\\\\\\\\n  render(<PlanImport initialPages={pages} />)\\\\\\\\n}\\\\\\\\n\\\\\\\\ndescribe('PlanImport', () => {\\\\\\\\n  it('伏図에서 읽은 通り芯을 라벨과 스팬으로 보여준다', () => {\\\\\\\\n    open([planPage])\\\\\\\\n\\\\\\\\n    const grid = screen.getByTestId('plan-import-grid-X')\\\\\\\\n    expect(grid.textContent).toContain('bX1')\\\\\\\\n    expect(grid.textContent).toContain('cX1')\\\\\\\\n    expect(grid.textContent).toContain('8700')\\\\\\\\n    expect(screen.getByTestId('plan-import-grid-Y').textContent).toContain(\\\\\\\\n      '10000',\\\\\\\\n    )\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('伏図 한 장마다 블록을 제목과 함께 보여준다', () => {\\\\\\\\n    open([planPage])\\\\\\\\n\\\\\\\\n    expect(screen.getByText('2階床伏図1/100')).toBeTruthy()\\\\\\\\n    expect(screen.getByText('R階床伏図1/100')).toBeTruthy()\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('軸組図의 階高를 라벨과 함께 보여준다', () => {\\\\\\\\n    open([elevationPage])\\\\\\\\n\\\\\\\\n    const elevation = screen.getByTestId('plan-import-elevation-0')\\\\\\\\n    expect(elevation.textContent).toContain('4480')\\\\\\\\n    expect(elevation.textContent).toContain('2FL')\\\\\\\\n    // 같은 높이의 라벨 둘은 둘 다 보인다 — 어느 쪽이 階인지 제품이 고르지 않는다\\\\\\\\n    expect(elevation.textContent).toContain('中央棟1FL')\\\\\\\\n    expect(elevation.textContent).toContain('基準GL')\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('読めなかった도면은 사유를 말한다 — 빈 화면으로 두지 않는다', () => {\\\\\\\\n    open([{ widthPt: 100, heightPt: 100, items: [] }])\\\\\\\\n\\\\\\\\n    expect(screen.getByTestId('plan-import-issues').textContent).toBeTruthy()\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('다른 층에 부재가 있으면 通り芯을 말없이 바꾸지 않는다', async () => {\\\\\\\\n    // 샘플 案件에는 이미 여러 층의 부재가 있다. 격자 index는 스팬 배열에 매여\\\\\\\\n    // 있어서, 스팬을 바꾸면 손대지 않은 층이 조용히 다른 자리로 옮겨간다\\\\\\\\n    const before = useAppStore.getState().project\\\\\\\\n    open([planPage])\\\\\\\\n\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-apply-0'))\\\\\\\\n\\\\\\\\n    await waitFor(() => {\\\\\\\\n      expect(screen.getByTestId('plan-import-result').textContent).toBeTruthy()\\\\\\\\n    })\\\\\\\\n    expect(useAppStore.getState().project.grid).toEqual(before.grid)\\\\\\\\n    // 동의를 묻는 칸은 거부를 본 뒤에 나온다\\\\\\\\n    expect(screen.getByTestId('plan-import-discard')).toBeTruthy()\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('동의하면 通り芯과 부재가 案件에 들어간다', async () => {\\\\\\\\n    open([planPage])\\\\\\\\n\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-apply-0'))\\\\\\\\n    await waitFor(() => screen.getByTestId('plan-import-discard'))\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-discard'))\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-apply-0'))\\\\\\\\n\\\\\\\\n    await waitFor(() => {\\\\\\\\n      const { project } = useAppStore.getState()\\\\\\\\n      expect(project.grid.xSpans).toEqual([8700, 8700, 1200])\\\\\\\\n      expect(project.grid.ySpans).toEqual([5000, 6000, 10000, 6000, 5000])\\\\\\\\n    })\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('取入 결과를 넣지 못한 符号과 사유로 보고한다', async () => {\\\\\\\\n    open([planPage])\\\\\\\\n\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-apply-0'))\\\\\\\\n    await waitFor(() => screen.getByTestId('plan-import-discard'))\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-discard'))\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-apply-0'))\\\\\\\\n\\\\\\\\n    await waitFor(() => {\\\\\\\\n      // 샘플 案件의 断面一覧에는 이 도면의 符号이 없다 — 지어내지 않고 사유를 말한다\\\\\\\\n      expect(screen.getByTestId('plan-import-result').textContent).toContain(\\\\\\\\n        'C51',\\\\\\\\n      )\\\\\\\\n    })\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('階高를 案件의 階로 넣는다 — 어느 레벨이 階인지는 사람이 고른다', async () => {\\\\\\\\n    open([elevationPage])\\\\\\\\n\\\\\\\\n    // 中央棟1FL(index 3)에서 中央棟RCL(index 1)까지 → 1階 4480·2階 4100.\\\\\\\\n    // パラペット(1400)와 基礎(2690)는 階가 아니므로 범위 밖이다\\\\\\\\n    fireEvent.change(screen.getByTestId('plan-import-level-top-0'), {\\\\\\\\n      target: { value: '1' },\\\\\\\\n    })\\\\\\\\n    fireEvent.change(screen.getByTestId('plan-import-level-bottom-0'), {\\\\\\\\n      target: { value: '3' },\\\\\\\\n    })\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-apply-elevation-0'))\\\\\\\\n\\\\\\\\n    // 샘플 案件에 부재가 있어 한 번 거부된다 — 동의는 그 뒤에만 나온다\\\\\\\\n    await waitFor(() =>\\\\\\\\n      screen.getByTestId('plan-import-discard-members-0'),\\\\\\\\n    )\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-discard-members-0'))\\\\\\\\n    fireEvent.click(screen.getByTestId('plan-import-apply-elevation-0'))\\\\\\\\n\\\\\\\\n    await waitFor(() => {\\\\\\\\n      const { stories } = useAppStore.getState().project\\\\\\\\n      expect(stories.map((story) => story.height)).toEqual([4480, 4100])\\\\\\\\n      expect(stories.map((story) => story.name)).toEqual([\\\\\\\\n        '中央棟1FL／基準GL',\\\\\\\\n        '2FL',\\\\\\\\n      ])\\\\\\\\n    })\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('階高 반영 전에는 案件의 階를 건드리지 않는다', () => {\\\\\\\\n    const before = useAppStore.getState().project.stories\\\\\\\\n    open([elevationPage])\\\\\\\\n\\\\\\\\n    expect(useAppStore.getState().project.stories).toBe(before)\\\\\\\\n  })\\\\\\\\n\\\\\\\\n  it('PDF 읽기에 실패하면 案件을 건드리지 않고 말한다', async () => {\\\\\\\\n    const before = useAppStore.getState().project\\\\\\\\n    render(\\\\\\\\n      <PlanImport\\\\\\\\n        extractPages={vi.fn().mockRejectedValue(new Error('broken'))}\\\\\\\\n      />,\\\\\\\\n    )\\\\\\\\n\\\\\\\\n    fireEvent.change(screen.getByTestId('plan-import-file'), {\\\\\\\\n      target: { files: [new File(['x'], 'a.pdf', { type: 'application/pdf' })] },\\\\\\\\n    })\\\\\\\\n\\\\\\\\n    await waitFor(() => {\\\\\\\\n      expect(screen.getByRole('alert')).toBeTruthy()\\\\\\\\n    })\\\\\\\\n    expect(useAppStore.getState().project).toBe(before)\\\\\\\\n  })\\\\\\\\n})\\\\\\\\n\\\\\\\\r\\\\\\\\n// UC-22: 伏図·軸組図 PDF에서 형상(通り芯·부재 배치·階高)을 읽고, 승인해야만\\\\\\\\n// 案件에 들어간다 (ADR-030). 断面リスト 취입(uc12)과 같은 규약이되 가드가 하나 더\\\\\\\\n// 있다 — 格子 index는 스팬 배열에 매여 있어서, 通り芯을 바꾸면 손대지 않은 층의\\\\\\\\n// 부재가 조용히 다른 자리로 옮겨간다. 그래서 다른 층에 부재가 있으면 통째로\\\\\\\\n// 거부하고, 거부를 한 번 보여준 뒤에만 「다른 층을 버린다」는 동의 칸을 낸다.\\\\\\\\nconst pdfPath = \\\\\\\\\\\\\\\".cache/dwg-yokohama.pdf\\\\\\\\\\\\\\\";\\\\\\\\nconst sandboxFixture = \\\\\\\\\\\\\\\"uc22-dwg-yokohama.pdf.b64\\\\\\\\\\\\\\\";\\\\\\\\nlet pdfBase64;\\\\\\\\ntry {\\\\\\\\n  // dev-browser는 QuickJS에서 호스트 경로를 직접 열 수 없다. AC 실행 전에 로컬\\\\\\\\n  // .cache PDF를 격리 temp에 base64로 미러링하며, 없으면 첫머리에서 명시적으로 실패한다.\\\\\\\\n  pdfBase64 = await readFile(sandboxFixture);\\\\\\\\n} catch (error) {\\\\\\\\n  throw new Error(\\\\\\\\n    `LOCAL FIXTURE MISSING: ${pdfPath} — 먼저 실행: ` +\\\\\\\\n      `base64 -w0 ${pdfPath} > ~/.dev-browser/tmp/${sandboxFixture} ` +\\\\\\\\n      `(재현 절차: tests/fixtures/section-import/SOURCES.md) (${String(error)})`,\\\\\\\\n  );\\\\\\\\n}\\\\\\\\n\\\\\\\\nconst page = await browser.getPage(\\\\\\\\\\\\\\\"kijun\\\\\\\\\\\\\\\");\\\\\\\\nawait page.goto(\\\\\\\\\\\\\\\"http://localhost:3000\\\\\\\\\\\\\\\", { waitUntil: \\\\\\\\\\\\\\\"domcontentloaded\\\\\\\\\\\\\\\" });\\\\\\\\n// 自動保存 (M4) が前の筋書きの編集を復元する。どの筋書きもサンプル案件から\\\\\\\\n// 始めたいので、最初の着地で記録を消してから読み直す。\\\\\\\\nawait page.evaluate(\\\\\\\\n  () =>\\\\\\\\n    new Promise((resolve) => {\\\\\\\\n      const request = indexedDB.deleteDatabase(\\\\\\\\\\\\\\\"kijun\\\\\\\\\\\\\\\");\\\\\\\\n      request.onsuccess = resolve;\\\\\\\\n      request.onerror = resolve;\\\\\\\\n      request.onblocked = resolve;\\\\\\\\n    }),\\\\\\\\n);\\\\\\\\nawait page.reload({ waitUntil: \\\\\\\\\\\\\\\"domcontentloaded\\\\\\\\\\\\\\\" });\\\\\\\\nawait page.waitForSelector(\\\\\\\\\\\\\\\"[data-testid='grand-total']\\\\\\\\\\\\\\\");\\\\\\\\nawait page.waitForSelector(\\\\\\\\\\\\\\\"canvas\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n// 案件의 通り芯은 DOM에서 읽는다 — 테스트만을 위한 전역 훅을 제품에 심지\\\\\\\\n// 않는다 (다른 UC와 같은 규약). 이름이 아니라 data-testid로 집는 이유가 있다:\\\\\\\\n// 도면에서 通り芯 이름을 읽어오면 aria-label이 「bX1-bX2」로 바뀐다.\\\\\\\\nconst readSpans = () =>\\\\\\\\n  page.evaluate(() => {\\\\\\\\n    const spans = (axis) =>\\\\\\\\n      [...document.querySelectorAll(`input[data-testid^='span-${axis}-']`)]\\\\\\\\n        .map((input) => input.value)\\\\\\\\n        .join(\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\");\\\\\\\\n    return { x: spans(\\\\\\\\\\\\\\\"x\\\\\\\\\\\\\\\"), y: spans(\\\\\\\\\\\\\\\"y\\\\\\\\\\\\\\\") };\\\\\\\\n  });\\\\\\\\n\\\\\\\\nconst beforeGrid = await readSpans();\\\\\\\\n\\\\\\\\nawait page.setInputFiles(\\\\\\\\\\\\\\\"[data-testid='plan-import-file']\\\\\\\\\\\\\\\", {\\\\\\\\n  name: \\\\\\\\\\\\\\\"dwg-yokohama.pdf\\\\\\\\\\\\\\\",\\\\\\\\n  mimeType: \\\\\\\\\\\\\\\"application/pdf\\\\\\\\\\\\\\\",\\\\\\\\n  buffer: Buffer.from(pdfBase64, \\\\\\\\\\\\\\\"base64\\\\\\\\\\\\\\\"),\\\\\\\\n});\\\\\\\\nawait page.waitForSelector(\\\\\\\\\\\\\\\"[data-testid='plan-import-grid-X']\\\\\\\\\\\\\\\", {\\\\\\\\n  timeout: 120000,\\\\\\\\n});\\\\\\\\n\\\\\\\\nconst read = await page.evaluate(() => {\\\\\\\\n  const text = (testId) =>\\\\\\\\n    document.querySelector(`[data-testid='${testId}']`)?.textContent ?? \\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\";\\\\\\\\n  return {\\\\\\\\n    // 通り芯: 라벨과 스팬이 도면 그대로\\\\\\\\n    gridX: text(\\\\\\\\\\\\\\\"plan-import-grid-X\\\\\\\\\\\\\\\"),\\\\\\\\n    gridY: text(\\\\\\\\\\\\\\\"plan-import-grid-Y\\\\\\\\\\\\\\\"),\\\\\\\\n    // 軸組図: 階高와 레벨 라벨 (같은 높이의 둘은 둘 다 남는다)\\\\\\\\n    elevation: text(\\\\\\\\\\\\\\\"plan-import-elevation-0\\\\\\\\\\\\\\\"),\\\\\\\\n    // 伏図 한 장마다 블록 — 이 PDF는 5장이다(杭·基礎·1階床·2階床·R階床)\\\\\\\\n    blockTitles: [...document.querySelectorAll(\\\\\\\\\\\\\\\"strong\\\\\\\\\\\\\\\")]\\\\\\\\n      .map((node) => node.textContent.trim())\\\\\\\\n      .filter((label) => label.includes(\\\\\\\\\\\\\\\"伏図\\\\\\\\\\\\\\\")),\\\\\\\\n  };\\\\\\\\n});\\\\\\\\n\\\\\\\\n// 반영은 「2階床伏図」 블록으로 한다 — index가 아니라 제목으로 고른다.\\\\\\\\n// 0번은 杭伏図이고 그 符号(P51 등)은 제품의 부재가 아니라 아무것도 안 들어간다.\\\\\\\\nconst targetApply = await page.evaluate(() => {\\\\\\\\n  const blocks = [...document.querySelectorAll(\\\\\\\\\\\\\\\"[data-testid^='plan-import-apply-']\\\\\\\\\\\\\\\")];\\\\\\\\n  const index = blocks.findIndex((button) =>\\\\\\\\n    button.closest(\\\\\\\\\\\\\\\"div\\\\\\\\\\\\\\\")?.textContent.includes(\\\\\\\\\\\\\\\"2階床伏図\\\\\\\\\\\\\\\"),\\\\\\\\n  );\\\\\\\\n  return index < 0 ? null : blocks[index].getAttribute(\\\\\\\\\\\\\\\"data-testid\\\\\\\\\\\\\\\");\\\\\\\\n});\\\\\\\\nif (!targetApply) throw new Error(\\\\\\\\\\\\\\\"2階床伏図 블록을 찾지 못했다\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\n// 1) 승인 전에는 案件이 바뀌지 않는다\\\\\\\\nconst untouched = await readSpans();\\\\\\\\n\\\\\\\\n// 2) 첫 반영은 거부된다 — 샘플 案件에 다른 층 부재가 있다\\\\\\\\nawait page.click(`[data-testid='${targetApply}']`);\\\\\\\\nawait page.waitForSelector(\\\\\\\\\\\\\\\"[data-testid='plan-import-result']\\\\\\\\\\\\\\\");\\\\\\\\nconst refusedPanel = await page.evaluate(() => ({\\\\\\\\n  message:\\\\\\\\n    document.querySelector(\\\\\\\\\\\\\\\"[data-testid='plan-import-result']\\\\\\\\\\\\\\\")?.textContent ??\\\\\\\\n    \\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\",\\\\\\\\n  consentOffered:\\\\\\\\n    document.querySelector(\\\\\\\\\\\\\\\"[data-testid='plan-import-discard']\\\\\\\\\\\\\\\") !== null,\\\\\\\\n}));\\\\\\\\nconst refused = { ...refusedPanel, spans: await readSpans() };\\\\\\\\n\\\\\\\\n// 3) 동의하면 들어간다\\\\\\\\nawait page.click(\\\\\\\\\\\\\\\"[data-testid='plan-import-discard']\\\\\\\\\\\\\\\");\\\\\\\\nawait page.click(`[data-testid='${targetApply}']`);\\\\\\\\nawait page.waitForTimeout(500);\\\\\\\\nconst appliedPanel = await page.evaluate(() => ({\\\\\\\\n  // 断面一覧에 없는 符号은 지어내지 않고 사유를 말한다\\\\\\\\n  result:\\\\\\\\n    document.querySelector(\\\\\\\\\\\\\\\"[data-testid='plan-import-result']\\\\\\\\\\\\\\\")?.textContent ??\\\\\\\\n    \\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\",\\\\\\\\n  grandTotal:\\\\\\\\n    document.querySelector(\\\\\\\\\\\\\\\"[data-testid='grand-total']\\\\\\\\\\\\\\\")?.textContent ?? null,\\\\\\\\n  paneFailures: [...document.querySelectorAll(\\\\\\\\\\\\\\\"[role='alert']\\\\\\\\\\\\\\\")].map(\\\\\\\\n    (node) => node.textContent,\\\\\\\\n  ),\\\\\\\\n}));\\\\\\\\nconst applied = { ...appliedPanel, spans: await readSpans() };\\\\\\\\n// 通り芯의 이름이 案件에 들어갔는가 — R13의 선결 조건이다\\\\\\\\nconst spanNames = await page.evaluate(() =>\\\\\\\\n  [...document.querySelectorAll(\\\\\\\\\\\\\\\"input[data-testid^='span-x-']\\\\\\\\\\\\\\\")].map((input) =>\\\\\\\\n    input.getAttribute(\\\\\\\\\\\\\\\"aria-label\\\\\\\\\\\\\\\"),\\\\\\\\n  ),\\\\\\\\n);\\\\\\\\n\\\\\\\\n// 4) 階高를 案件의 階로 넣는다 — 어느 레벨이 階인지는 사람이 고른다.\\\\\\\\n// 中央棟1FL(index 3)에서 中央棟RCL(index 1)까지 → 1階 4480·2階 4100.\\\\\\\\n// パラペット(1400)와 基礎(2690)는 階가 아니므로 범위 밖이다\\\\\\\\nawait page.selectOption(\\\\\\\\\\\\\\\"[data-testid='plan-import-level-top-0']\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\"1\\\\\\\\\\\\\\\");\\\\\\\\nawait page.selectOption(\\\\\\\\\\\\\\\"[data-testid='plan-import-level-bottom-0']\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\"3\\\\\\\\\\\\\\\");\\\\\\\\nawait page.click(\\\\\\\\\\\\\\\"[data-testid='plan-import-apply-elevation-0']\\\\\\\\\\\\\\\");\\\\\\\\nawait page.waitForSelector(\\\\\\\\\\\\\\\"[data-testid='plan-import-elevation-result-0']\\\\\\\\\\\\\\\");\\\\\\\\nconst storyRefused = await page.evaluate(() => ({\\\\\\\\n  message:\\\\\\\\n    document.querySelector(\\\\\\\\\\\\\\\"[data-testid='plan-import-elevation-result-0']\\\\\\\\\\\\\\\")\\\\\\\\n      ?.textContent ?? \\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\",\\\\\\\\n  consentOffered:\\\\\\\\n    document.querySelector(\\\\\\\\\\\\\\\"[data-testid='plan-import-discard-members-0']\\\\\\\\\\\\\\\") !==\\\\\\\\n    null,\\\\\\\\n}));\\\\\\\\nif (storyRefused.consentOffered) {\\\\\\\\n  await page.click(\\\\\\\\\\\\\\\"[data-testid='plan-import-discard-members-0']\\\\\\\\\\\\\\\");\\\\\\\\n  await page.click(\\\\\\\\\\\\\\\"[data-testid='plan-import-apply-elevation-0']\\\\\\\\\\\\\\\");\\\\\\\\n  await page.waitForTimeout(500);\\\\\\\\n}\\\\\\\\n// 階 이름은 層 탭(role=tab)에서 읽는다 — 스팬과 같이 DOM이 유일한 창구다.\\\\\\\\n// 뷰어 탭(部材·建物)도 role=tab이라 목록에는 그것들도 섞인다 — 개수가 아니라\\\\\\\\n// 「도면에서 온 이름이 거기 있는가」를 본다\\\\\\\\nconst stories = await page.evaluate(() =>\\\\\\\\n  [...document.querySelectorAll(\\\\\\\\\\\\\\\"[role='tab']\\\\\\\\\\\\\\\")].map((node) =>\\\\\\\\n    node.textContent.trim(),\\\\\\\\n  ),\\\\\\\\n);\\\\\\\\n\\\\\\\\nconst checks = {\\\\\\\\n  gridXLabelsRead:\\\\\\\\n    read.gridX.includes(\\\\\\\\\\\\\\\"bX1\\\\\\\\\\\\\\\") && read.gridX.includes(\\\\\\\\\\\\\\\"cX1\\\\\\\\\\\\\\\"),\\\\\\\\n  gridXSpansRead: read.gridX.includes(\\\\\\\\\\\\\\\"8700\\\\\\\\\\\\\\\") && read.gridX.includes(\\\\\\\\\\\\\\\"1200\\\\\\\\\\\\\\\"),\\\\\\\\n  gridYSpansRead: read.gridY.includes(\\\\\\\\\\\\\\\"10000\\\\\\\\\\\\\\\"),\\\\\\\\n  allPlanBlocksRead: read.blockTitles.length === 5,\\\\\\\\n  elevationHeightsRead: read.elevation.includes(\\\\\\\\\\\\\\\"4480\\\\\\\\\\\\\\\"),\\\\\\\\n  // 같은 높이의 라벨 둘은 둘 다 보인다 — 어느 쪽이 階인지 제품이 고르지 않는다\\\\\\\\n  elevationAmbiguousLevelsKept:\\\\\\\\n    read.elevation.includes(\\\\\\\\\\\\\\\"中央棟1FL\\\\\\\\\\\\\\\") && read.elevation.includes(\\\\\\\\\\\\\\\"基準GL\\\\\\\\\\\\\\\"),\\\\\\\\n  untouchedBeforeApproval:\\\\\\\\n    untouched.x === beforeGrid.x && untouched.y === beforeGrid.y,\\\\\\\\n  firstApplyRefused:\\\\\\\\n    refused.spans.x === beforeGrid.x && refused.spans.y === beforeGrid.y,\\\\\\\\n  consentOfferedAfterRefusal: refused.consentOffered === true,\\\\\\\\n  gridAppliedAfterConsent:\\\\\\\\n    applied.spans.x === \\\\\\\\\\\\\\\"8700,8700,1200\\\\\\\\\\\\\\\" &&\\\\\\\\n    applied.spans.y === \\\\\\\\\\\\\\\"5000,6000,10000,6000,5000\\\\\\\\\\\\\\\",\\\\\\\\n  // 샘플 案件의 断面一覧에는 이 도면의 符号이 없다 — 지어내지 않고 사유를 말한다\\\\\\\\n  missingSectionsReported:\\\\\\\\n    applied.result.includes(\\\\\\\\\\\\\\\"C51\\\\\\\\\\\\\\\") && applied.result.includes(\\\\\\\\\\\\\\\"断面一覧\\\\\\\\\\\\\\\"),\\\\\\\\n  // 部材가 0본이 되어도 화면은 선다 — 割増는 引く 대상이 없을 뿐 오류가 아니다\\\\\\\\n  takeoffStillRenders: applied.grandTotal !== null,\\\\\\\\n  noPaneFailure: applied.paneFailures.length === 0,\\\\\\\\n  gridLabelsApplied: spanNames.join(\\\\\\\\\\\\\\\",\\\\\\\\\\\\\\\") === \\\\\\\\\\\\\\\"bX1-bX2,bX2-bX3,bX3-cX1\\\\\\\\\\\\\\\",\\\\\\\\n  // 階高: 고른 범위(1FL→RCL)의 두 칸만 階가 된다. パラペット·基礎는 범위 밖이다.\\\\\\\\n  // 이 시점에는 앞의 通り芯 반영이 이미 부재를 비웠으므로 거부가 나지 않는다 —\\\\\\\\n  // 부재가 남아 있을 때의 거부는 단위 테스트가 고정한다\\\\\\\\n  storiesApplied: storyRefused.message.includes(\\\\\\\\\\\\\\\"2\\\\\\\\\\\\\\\"),\\\\\\\\n  // 이름은 그 階의 바닥이 되는 레벨의 원문 그대로다 — 지어내지 않고,\\\\\\\\n  // 같은 높이의 라벨 둘은 둘 다 남는다\\\\\\\\n  storiesNamedFromDrawing:\\\\\\\\n    stories.includes(\\\\\\\\\\\\\\\"中央棟1FL／基準GL\\\\\\\\\\\\\\\") && stories.includes(\\\\\\\\\\\\\\\"2FL\\\\\\\\\\\\\\\"),\\\\\\\\n};\\\\\\\\n\\\\\\\\nconsole.log(JSON.stringify({ read, refused, applied, spanNames, storyRefused, stories, checks }, null, 2));\\\\\\\\nconsole.log(\\\\\\\\n  \\\\\\\\\\\\\\\"SHOT \\\\\\\\\\\\\\\" + (await saveScreenshot(await page.screenshot(), \\\\\\\\\\\\\\\"uc22-plan-import.png\\\\\\\\\\\\\\\")),\\\\\\\\n);\\\\\\\\n\\\\\\\\nconst failed = Object.entries(checks)\\\\\\\\n  .filter(([, ok]) => !ok)\\\\\\\\n  .map(([name]) => name);\\\\\\\\nif (failed.length) throw new Error(\\\\\\\\\\\\\\\"FAILED CHECKS: \\\\\\\\\\\\\\\" + failed.join(\\\\\\\\\\\\\\\", \\\\\\\\\\\\\\\"));\\\\\\\\nconsole.log(\\\\\\\\\\\\\\\"ALL CHECKS PASSED\\\\\\\\\\\\\\\");\\\\\\\\n\\\\\\\\r\\\\\\\\n{\\\\\\\\r\\\\\\\\n  \\\\\\\\\\\\\\\"name\\\\\\\\\\\\\\\": \\\\\\\\\\\\\\\"kijun\\\\\\\\\\\\\\\",\\\\\\\\r\\\\\\\\n  \\\\\\\\\\\\\\\"version\\\\\\\\\\\\\\\": \\\\\\\\\\\\\\\"0.1.0\\\\\\\\\\\\\\\",\\\\\\\\r\\\\\\\\n  \\\\\\\\\\\\\\\"private\\\\\\\\\\\\\\\": true,\\\\\\\\r\\\\\\\\n  \\\\\\\\\\\\\\\"type\\\\\\\\\\\\\\\": \\\\\\\\\\\\\\\"module\\\\\\\\\\\\\\\",\\\\\\\\r\\\\\\\\n  \\\\\\\\\\\\\\\"scripts\\\\\\\\\\\\\\\": {\\\\\\\\r\\\\\\\\n    \\\\\\\\\\\\\\\"dev\\\\\\\\\\\\\\\": \\\\