idate.direction}`}>\\\\\\\\r\\\\\\\\n      <h4 className={styles.groupTitle}>{label}</h4>\\\\\\\\r\\\\\\\\n      <p className={styles.axes}>\\\\\\\\r\\\\\\\\n        {candidate.axes.map((axis, index) => (\\\\\\\\r\\\\\\\\n          <span key={`${axis.label}-${index}`}>\\\\\\\\r\\\\\\\\n            <span className={styles.axis}>{axis.label}</span>\\\\\\\\r\\\\\\\\n            {index < candidate.spansMm.length ? (\\\\\\\\r\\\\\\\\n              <span className={styles.span}>\\\\\\\\r\\\\\\\\n                {` — ${candidate.spansMm[index]} — `}\\\\\\\\r\\\\\\\\n              </span>\\\\\\\\r\\\\\\\\n            ) : null}\\\\\\\\r\\\\\\\\n          </span>\\\\\\\\r\\\\\\\\n        ))}\\\\\\\\r\\\\\\\\n      </p>\\\\\\\\r\\\\\\\\n    </div>\\\\\\\\r\\\\\\\\n  )\\\\\\\\r\\\\\\\\n}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nfunction Elevation({\\\\\\\\r\\\\\\\\n  candidate,\\\\\\\\r\\\\\\\\n  index,\\\\\\\\r\\\\\\\\n  locale,\\\\\\\\r\\\\\\\\n  onApply,\\\\\\\\r\\\\\\\\n  result,\\\\\\\\r\\\\\\\\n  discardMembers,\\\\\\\\r\\\\\\\\n  onDiscardMembersChange,\\\\\\\\r\\\\\\\\n}: {\\\\\\\\r\\\\\\\\n  candidate: ElevationCandidate\\\\\\\\r\\\\\\\\n  index: number\\\\\\\\r\\\\\\\\n  locale: 'ja' | 'ko'\\\\\\\\r\\\\\\\\n  onApply: (topLevelIndex: number, bottomLevelIndex: number) => void\\\\\\\\r\\\\\\\\n  result: ElevationApplyResult | null\\\\\\\\r\\\\\\\\n  discardMembers: boolean\\\\\\\\r\\\\\\\\n  onDiscardMembersChange: (next: boolean) => void\\\\\\\\r\\\\\\\\n}) {\\\\\\\\r\\\\\\\\n  // 「어느 레벨이 階의 경계인가」는 조문이 아니라 설계 의도라 사람이 고른다\\\\\\\\r\\\\\\\\n  // (ADR-030). 기본값은 양 끝 — 제품은 パラペット이나 基礎를 알아볼 수 없으므로\\\\\\\\r\\\\\\\\n  // 가장 넓게 잡아 두고 사용자가 좁힌다\\\\\\\\r\\\\\\\\n  const [top, setTop] = useState(0)\\\\\\\\r\\\\\\\\n  const [bottom, setBottom] = useState(candidate.levels.length - 1)\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\n  const levelLabel = (levelIndex: number) => {\\\\\\\\r\\\\\\\\n    const level = candidate.levels[levelIndex]\\\\\\\\r\\\\\\\\n    return level.labels.length > 0\\\\\\\\r\\\\\\\\n      ? level.labels.join('／')\\\\\\\\r\\\\\\\\n      : t(locale, 'planImport.levelUnlabelled')\\\\\\\\r\\\\\\\\n  }\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\n  return (\\\\\\\\r\\\\\\\\n    <div\\\\\\\\r\\\\\\\\n      className={styles.elevation}\\\\\\\\r\\\\\\\\n      data-testid={`plan-import-elevation-${index}`}\\\\\\\\r\\\\\\\\n    >\\\\\\\\r\\\\\\\\n      <div className={styles.blockHeading}>\\\\\\\\r\\\\\\\\n        <strong>\\\\\\\\r\\\\\\\\n          {candidate.titles.join('・') ||\\\\\\\\r\\\\\\\\n            t(locale, 'planImport.elevationUntitled')}\\\\\\\\r\\\\\\\\n        </strong>\\\\\\\\r\\\\\\\\n        <button\\\\\\\\r\\\\\\\\n          type=\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n          className={styles.applyButton}\\\\\\\\r\\\\\\\\n          data-testid={`plan-import-apply-elevation-${index}`}\\\\\\\\r\\\\\\\\n          onClick={() => onApply(top, bottom)}\\\\\\\\r\\\\\\\\n        >\\\\\\\\r\\\\\\\\n          {t(locale, 'planImport.applyStories')}\\\\\\\\r\\\\\\\\n        </button>\\\\\\\\r\\\\\\\\n      </div>\\\\\\\\r\\\\\\\\n      <p className={styles.axes}>\\\\\\\\r\\\\\\\\n        {candidate.levels.map((level, levelIndex) => (\\\\\\\\r\\\\\\\\n          <span key={levelIndex}>\\\\\\\\r\\\\\\\\n            <span className={styles.axis}>\\\\\\\\r\\\\\\\\n              {level.labels.join('／') || '—'}\\\\\\\\r\\\\\\\\n            </span>\\\\\\\\r\\\\\\\\n            {levelIndex < candidate.heightsMm.length ? (\\\\\\\\r\\\\\\\\n              <span className={styles.span}>\\\\\\\\r\\\\\\\\n                {` — ${candidate.heightsMm[levelIndex]} — `}\\\\\\\\r\\\\\\\\n              </span>\\\\\\\\r\\\\\\\\n            ) : null}\\\\\\\\r\\\\\\\\n          </span>\\\\\\\\r\\\\\\\\n        ))}\\\\\\\\r\\\\\\\\n      </p>\\\\\\\\r\\\\\\\\n      <div className={styles.storyPicker}>\\\\\\\\r\\\\\\\\n        <label className={styles.storyPicker}>\\\\\\\\r\\\\\\\\n          {t(locale, 'planImport.topLevel')}\\\\\\\\r\\\\\\\\n          <select\\\\\\\\r\\\\\\\\n            data-testid={`plan-import-level-top-${index}`}\\\\\\\\r\\\\\\\\n            value={top}\\\\\\\\r\\\\\\\\n            onChange={(event) => setTop(Number(event.target.value))}\\\\\\\\r\\\\\\\\n          >\\\\\\\\r\\\\\\\\n            {candidate.levels.map((level, levelIndex) => (\\\\\\\\r\\\\\\\\n              <option key={levelIndex} value={levelIndex}>\\\\\\\\r\\\\\\\\n                {levelLabel(levelIndex)}\\\\\\\\r\\\\\\\\n              </option>\\\\\\\\r\\\\\\\\n            ))}\\\\\\\\r\\\\\\\\n          </select>\\\\\\\\r\\\\\\\\n        </label>\\\\\\\\r\\\\\\\\n        <label className={styles.storyPicker}>\\\\\\\\r\\\\\\\\n          {t(locale, 'planImport.bottomLevel')}\\\\\\\\r\\\\\\\\n          <select\\\\\\\\r\\\\\\\\n            data-testid={`plan-import-level-bottom-${index}`}\\\\\\\\r\\\\\\\\n            value={bottom}\\\\\\\\r\\\\\\\\n            onChange={(event) => setBottom(Number(event.target.value))}\\\\\\\\r\\\\\\\\n          >\\\\\\\\r\\\\\\\\n            {candidate.levels.map((level, levelIndex) => (\\\\\\\\r\\\\\\\\n              <option key={levelIndex} value={levelIndex}>\\\\\\\\r\\\\\\\\n                {levelLabel(levelIndex)}\\\\\\\\r\\\\\\\\n              </option>\\\\\\\\r\\\\\\\\n            ))}\\\\\\\\r\\\\\\\\n          </select>\\\\\\\\r\\\\\\\\n        </label>\\\\\\\\r\\\\\\\\n      </div>\\\\\\\\r\\\\\\\\n      {/* 동의는 거부를 한 번 본 뒤에만 물어본다 */}\\\\\\\\r\\\\\\\\n      {result?.refusal === '部材あり階置換不可' ? (\\\\\\\\r\\\\\\\\n        <label className={styles.storyPicker}>\\\\\\\\r\\\\\\\\n          <input\\\\\\\\r\\\\\\\\n            type=\\\\\\\\\\\\\\\"checkbox\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n            data-testid={`plan-import-discard-members-${index}`}\\\\\\\\r\\\\\\\\n            checked={discardMembers}\\\\\\\\r\\\\\\\\n            onChange={(event) => onDiscardMembersChange(event.target.checked)}        yGrid,          else inputRef.current?.click()\\\\\\\\r\\\\\\\\n        }}\\\\\\\\r\\\\\\\\n      >\\\\\\\\r\\\\\\\\n        {t(locale, 'planImport.open')}\\\\\\\\r\\\\\\\\n      </button>\\\\\\\\r\\\\\\\\n      <input\\\\\\\\r\\\\\\\\n        ref={inputRef}\\\\\\\\r\\\\\\\\n        className={styles.fileInput}\\\\\\\\r\\\\\\\\n        data-testid=\\\\\\\\\\\\\\\"plan-import-file\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n        type=\\\\\\\\\\\\\\\"file\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n        accept=\\\\\\\\\\\\\\\"application/pdf\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n        aria-label={t(locale, 'planImport.file')}\\\\\\\\r\\\\\\\\n        onChange={(event) => void selectFile(event)}\\\\\\\\r\\\\\\\\n      />\\\\\\\\r\\\\\\\\n      {open ? (\\\\\\\\r\\\\\\\\n        <section\\\\\\\\r\\\\\\\\n          className={styles.panel}\\\\\\\\r\\\\\\\\n          role=\\\\\\\\\\\\\\\"dialog\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n          aria-modal=\\\\\\\\\\\\\\\"false\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n          aria-labelledby=\\\\\\\\\\\\\\\"plan-import-title\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n        >\\\\\\\\r\\\\\\\\n          <header className={styles.panelHeader}>\\\\\\\\r\\\\\\\\n            <h3 id=\\\\\\\\\\\\\\\"plan-import-title\\\\\\\\\\\\\\\">{t(locale, 'planImport.title')}</h3>\\\\\\\\r\\\\\\\\n            <div className={styles.panelActions}>\\\\\\\\r\\\\\\\\n              <button\\\\\\\\r\\\\\\\\n                type=\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n                className={styles.chooseButton}\\\\\\\\r\\\\\\\\n                onClick={() => inputRef.current?.click()}\\\\\\\\r\\\\\\\\n              >\\\\\\\\r\\\\\\\\n                {t(locale, 'planImport.chooseAnother')}\\\\\\\\r\\\\\\\\n              </button>\\\\\\\\r\\\\\\\\n              <button\\\\\\\\r\\\\\\\\n                type=\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n                className={styles.closeButton}\\\\\\\\r\\\\\\\\n                onClick={() => setOpen(false)}\\\\\\\\r\\\\\\\\n              >\\\\\\\\r\\\\\\\\n                {t(locale, 'planImport.close')}\\\\\\\\r\\\\\\\\n              </button>\\\\\\\\r\\\\\\\\n            </div>\\\\\\\\r\\\\\\\\n          </header>\\\\\\\\r\\\\\\\\n          <div className={styles.panelBody}>\\\\\\\\r\\\\\\\\n            {loading ? (\\\\\\\\r\\\\\\\\n              <p role=\\\\\\\\\\\\\\\"status\\\\\\\\\\\\\\\">{t(locale, 'planImport.loading')}</p>\\\\\\\\r\\\\\\\\n            ) : failed ? (\\\\\\\\r\\\\\\\\n              <p role=\\\\\\\\\\\\\\\"alert\\\\\\\\\\\\\\\">{t(locale, 'planImport.error')}</p>\\\\\\\\r\\\\\\\\n            ) : (\\\\\\\\r\\\\\\\\n              <>\\\\\\\\r\\\\\\\\n                {issues.length > 0 ? (\\\\\\\\r\\\\\\\\n                  <ul className={styles.issues} data-testid=\\\\\\\\\\\\\\\"plan-import-issues\\\\\\\\\\\\\\\">\\\\\\\\r\\\\\\\\n                    {issues.map((issue) => (\\\\\\\\r\\\\\\\\n                      <li key={issue}>\\\\\\\\r\\\\\\\\n                        {t(locale, `planImport.issue.${issue}`)}\\\\\\\\r\\\\\\\\n                      </li>\\\\\\\\r\\\\\\\\n                    ))}\\\\\\\\r\\\\\\\\n                  </ul>\\\\\\\\r\\\\\\\\n                ) : null}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\n                {xGrid ? (\\\\\\\\r\\\\\\\\n                  <Axes candidate={xGrid} label={t(locale, 'planImport.gridX')} />\\\\\\\\r\\\\\\\\n                ) : null}\\\\\\\\r\\\\\\\\n                {yGrid ? (\\\\\\\\r\\\\\\\\n                  <Axes candidate={yGrid} label={t(locale, 'planImport.gridY')} />\\\\\\\\r\\\\\\\\n                ) : null}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\n                {blocks.length > 0 ? (\\\\\\\\r\\\\\\\\n                  <label className={styles.storyPicker}>\\\\\\\\r\\\\\\\\n                    {t(locale, 'planImport.story')}\\\\\\\\r\\\\\\\\n                    <select\\\\\\\\r\\\\\\\\n                      data-testid=\\\\\\\\\\\\\\\"plan-import-story\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n                      value={storyId}\\\\\\\\r\\\\\\\\n                      onChange={(event) => setStoryId(event.target.value)}\\\\\\\\r\\\\\\\\n                    >\\\\\\\\r\\\\\\\\n                      {stories.map((story) => (\\\\\\\\r\\\\\\\\n                        <option key={story.id} value={story.id}>\\\\\\\\r\\\\\\\\n                          {story.name}\\\\\\\\r\\\\\\\\n                        </option>\\\\\\\\r\\\\\\\\n                      ))}\\\\\\\\r\\\\\\\\n                    </select>\\\\\\\\r\\\\\\\\n                  </label>\\\\\\\\r\\\\\\\\n                ) : null}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\n                {blocks.map((block, index) => (\\\\\\\\r\\\\\\\\n                  <div\\\\\\\\r\\\\\\\\n                    key={`${block.title ?? 'block'}-${index}`}\\\\\\\\r\\\\\\\\n                    className={styles.block}\\\\\\\\r\\\\\\\\n                  >                {result?.refusal === '他階部材あり通り芯変更不可' ? (\\\\\\\\r\\\\\\\\n                  <label className={styles.storyPicker}>\\\\\\\\r\\\\\\\\n                    <input\\\\\\\\r\\\\\\\\n                      type=\\\\\\\\\\\\\\\"checkbox\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n                      data-testid=\\\\\\\\\\\\\\\"plan-import-discard\\\\\\\\\\\\\\\"\\\\\\\\r\\\\\\\\n                      checked={discardOtherStories}\\\\\\\\r\\\\\\\\n                      onChange={(event) =>\\\\\\\\r\\\\\\\\n                        setDiscardOtherStories(event.target.checked)\\\\\\\\r\\\\\\\\n                      }\\\\\\\\r\\\\\\\\n                    />\\\\\\\\r\\\\\\\\n                    {t(locale, 'planImport.discardOtherStories')}\\\\\\\\r\\\\\\\\n                  </label>\\\\\\\\r\\\\\\\\n                ) : null}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\n                {result ? (\\\\\\\\r\\\\\\\\n                  <p className={styles.muted} data-testid=\\\\\\\\\\\\\\\"plan-import-result\\\\\\\\\\\\\\\">\\\\\\\\r\\\\\\\\n                    {result.refusal\\\\\\\\r\\\\\\\\n                      ? t(locale, `planImport.refusal.${result.refusal}`)\\\\\\\\r\\\\\\\\n                      : `${t(locale, 'planImport.applied')}: ${result.applied}`}\\\\\\\\r\\\\\\\\n                    {result.skipped.length > 0\\\\\\\\r\\\\\\\\n                      ? ` / ${result.skipped\\\\\\\\r\\\\\\\\n                          .map(\\\\\\\\r\\\\\\\\n                            ({ mark, reason }) =>\\\\\\\\r\\\\\\\\n                              `${mark}(${t(locale, `planImport.skip.${reason}`)})`,\\\\\\\\r\\\\\\\\n                          )\\\\\\\\r\\\\\\\\n                          .join('、')}`\\\\\\\\r\\\\\\\\n                      : ''}\\\\\\\\r\\\\\\\\n                  </p>\\\\\\\\r\\\\\\\\n                ) : null}\\\\\\\\r\\\\\\\\n              </>\\\\\\\\r\\\\\\\\n            )}\\\\\\\\r\\\\\\\\n          </div>\\\\\\\\r\\\\\\\\n        </section>\\\\\\\\r\\\\\\\\n      ) : null}\\\\\\\\r\\\\\\\\n    </div>\\\\\\\\r\\\\\\\\n  )\\\\\\\\r\\\\\\\\n}\\\\\\\\r\\\\\\\\n\\\\\\\",\\\\\\\"exit_code\\\\\\\":0,\\\\\\\"status\\\\\\\":\\\\\\\"completed\\\\\\\"}}\\\\n{\\\\\\\"type\\\\\\\":\\\\\\\"item.completed\\\\\\\",\\\\\\\"item\\\\\\\":{\\\\\\\"id\\\\\\\":\\\\\\\"item_13\\\\\\\",\\\\\\\"type\\\\\\\":\\\\\\\"command_execution\\\\\\\",\\\\\\\"command\\\\\\\":\\\\\\\"\\\\\\\\\\\\\\\"C:\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\WINDOWS\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\System32\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\WindowsPowerShell\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\v1.0\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\powershell.exe\\\\\\\\\\\\\\\" -Command 'Get-Content -Encoding utf8 src/lib/import/framing-plan/apply.test.ts'\\\\\\\",\\\\\\\"aggregated_output\\\\\\\":\\\\\\\"import { describe, expect, it } from 'vitest'\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nimport type { Section } from '@/domain/model/member'\\\\\\\\r\\\\\\\\nimport type { Project } from '@/domain/model/project'\\\\\\\\r\\\\\\\\nimport { createSampleProject } from '@/domain/model/sample-project'\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nimport { applyElevation, applyFramingPlan } from './apply'\\\\\\\\r\\\\\\\\nimport type {\\\\\\\\r\\\\\\\\n  ElevationCandidate,\\\\\\\\r\\\\\\\\n  PlanBlock,\\\\\\\\r\\\\\\\\n  PlanGridCandidate,\\\\\\\\r\\\\\\\\n} from './types'\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\n// 断面은 손으로 짓지 않고 샘플 案件에서 빌린다 — 손으로 지으면 스키마가 자라날 때\\\\\\\\r\\\\\\\\n// 이 테스트만 옛 모양으로 남고, 그 사실을 vitest는 알려주지 않는다 (tsc가 잡는다)\\\\\\\\r\\\\\\\\nconst sample = createSampleProject()\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nfunction sectionOf(kind: Section['kind'], mark: string): Section {\\\\\\\\r\\\\\\\\n  const source = sample.sections.find((section) => section.kind === kind)\\\\\\\\r\\\\\\\\n  if (!source) throw new Error(`sample has no ${kind} section`)\\\\\\\\r\\\\\\\\n  return { ...source, id: `sec-${mark}`, mark }\\\\\\\\r\\\\\\\\n}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nconst columnSection = (mark: string) => sectionOf('柱', mark)\\\\\\\\r\\\\\\\\nconst girderSection = (mark: string) => sectionOf('大梁', mark)\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nfunction project(overrides: Partial<Project> = {}): Project {\\\\\\\\r\\\\\\\\n  return {\\\\\\\\r\\\\\\\\n    schemaVersion: 11,\\\\\\\\r\\\\\\\\n    name: 'test',\\\\\\\\r\\\\\\\\n    grid: { xSpans: [6000], ySpans: [6000] },\\\\\\\\r\\\\\\\\n    stories: [{ id: 'story-1', name: '1F', height: 4000 }],\\\\\\\\r\\\\\\\\n    sections: [],\\\\\\\\r\\\\\\\\n    members: [],\\\\\\\\r\\\\\\\\n    ...overrides,\\\\\\\\r\\\\\\\\n  }\\\\\\\\r\\\\\\\\n}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nconst xGrid: PlanGridCandidate = {\\\\\\\\r\\\\\\\\n  direction: 'X',\\\\\\\\r\\\\\\\\n  axes: [\\\\\\\\r\\\\\\\\n    { label: 'X1', positionPt: 0 },\\\\\\\\r\\\\\\\\n    { label: 'X2', positionPt: 200 },\\\\\\\\r\\\\\\\\n    { label: 'X3', positionPt: 400 },\\\\\\\\r\\\\\\\\n  ],\\\\\\\\r\\\\\\\\n  spansMm: [7000, 7000],\\\\\\\\r\\\\\\\\n  scalePtPerMm: 200 / 7000,\\\\\\\\r\\\\\\\\n  totalConfirmed: false,\\\\\\\\r\\\\\\\\n}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nconst yGrid: PlanGridCandidate = {\\\\\\\\r\\\\\\\\n  direction: 'Y',\\\\\\\\r\\\\\\\\n  axes: [\\\\\\\\r\\\\\\\\n    { label: 'Y1', positionPt: 0 },\\\\\\\\r\\\\\\\\n    { label: 'Y2', positionPt: 200 },\\\\\\\\r\\\\\\\\n  ],\\\\\\\\r\\\\\\\\n  spansMm: [5000],\\\\\\\\r\\\\\\\\n  scalePtPerMm: 200 / 5000,\\\\\\\\r\\\\\\\\n  totalConfirmed: false,\\\\\\\\r\\\\\\\\n}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\nfunction block(overrides: Partial<PlanBlock> = {}): PlanBlock {\\\\\\\\r\\\\\\\\n  return {\\\\\\\\r\\\\\\\\n    xAxes: xGrid.axes,\\\\\\\\r\\\\\\\\n    yAxes: yGrid.axes,\\\\\\\\r\\\\\\\\n    placements: [],\\\\\\\\r\\\\\\\\n    unplacedMarks: [],\\\\\\\\r\\\\\\\\n    ...overrides,\\\\\\\\r\\\\\\\\n  }\\\\\\\\r\\\\\\\\n}\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\ndescribe('applyFramingPlan', () => {\\\\\\\\r\\\\\\\\n  it('通り芯을 도면의 스팬으로 바꾼다', () => {\\\\\\\\r\\\\\\\\n    const result = applyFramingPlan(project(), {\\\\\\\\r\\\\\\\\n      xGrid,\\\\\\\\r\\\\\\\\n      yGrid,\\\\\\\\r\\\\\\\\n      block: block(),\\\\\\\\r\\\\\\\\n      storyId: 'story-1',\\\\\\\\r\\\\\\\\n    })\\\\\\\\r\\\\\\\\n    expect(result.project.grid).toEqual({\\\\\\\\r\\\\\\\\n      xSpans: [7000, 7000],\\\\\\\\r\\\\\\\\n      ySpans: [5000],\\\\\\\\r\\\\\\\\n      xLabels: ['X1', 'X2', 'X3'],\\\\\\\\r\\\\\\\\n      yLabels: ['Y1', 'Y2'],\\\\\\\\r\\\\\\\\n    })\\\\\\\\r\\\\\\\\n    expect(result.refusal).toBeUndefined()\\\\\\\\r\\\\\\\\n  })\\\\\\\\r\\\\\\\\n\\\\\\\\r\\\\\\\\n  it('通り芯의 이름을 도면에서 읽은 원문 그대로 싣는다', () => {\\\\\\\\r\\\\\\\\n    // 이것이 R13(端部 좌우 비대칭)의 선결 조건이다 — 이름이 있어야 도면의\\\\\\\\r\\\\\\\\n    // 「Y3端／Y4端」을 런의 실제 방향과 맞출 수 있다\\\\\\\\r\\\\\\\\n    const result = applyFramingPlan(project(), {\\\\\\\\r\\\\\\\\n      xGrid,\\\\\\\\r\\\\\\\\n      yGrid,\\\\\\\\r\\\\\\\\n      block: block(),\\\\\\\\r\\\\\\\\n      storyId: 'story-1',\\\\\\\\r\\\\\\\\n    })\\\\\\\\r\\\\\\\\n    expect(result.project.grid.xLabels).toEqual(['X1', 'X2', 'X3'])\\\\\\\\r\\\\\\\\n    expect(result.project.grid.yLabels).toEqual(['Y1', 'Y2'])\\\\\\\\r\\\\\\\\n    expect(result.project.members).toEqual([])\\\\\\\\r\\\\\\\\n      sections: [columnSection('C1')],\\\\\\\\r\\\\\\\\n     