Grid = grids.find((grid) => grid.direction === 'Y')\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n  const blocks: PlanBlock[] = plans.flatMap((plan) => plan.blocks)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n  // 사유는 페이지마다 나오므로 접는다 — 같은 말이 페이지 수만큼 늘어서면 읽히지 않는다\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n  const issues = [...new Set(plans.flatMap((plan) => plan.issues))]\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n  const selectFile = async (event: ChangeEvent<HTMLInputElement>) => {\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    const input = event.currentTarget\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    const file = input.files?.[0]\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    if (!file) return\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    const requestId = ++requestRef.current\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    setOpen(true)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    setLoading(true)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    setFailed(false)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    setResult(null)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    setElevationResults({})\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    try {\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n      const next = await extractPages(file)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n      if (requestRef.current !== requestId) return\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n      setPages(next)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    } catch {\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n      if (requestRef.current !== requestId) return\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n      setPages(null)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n      setFailed(true)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    } finally {\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n      if (requestRef.current === requestId) setLoading(false)\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n      input.value = ''\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    }\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n  }\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n  const apply = (block: PlanBlock) => {\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n    if (!xGrid || !yGrid) return\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\