                {yGrid ? (\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                  <Axes candidate={yGrid} label={t(locale, 'planImport.gridY')} />\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                ) : null}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                {blocks.length > 0 ? (\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                  <label className={styles.storyPicker}>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    {t(locale, 'planImport.story')}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    <select\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      data-testid=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"plan-import-story\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      value={storyId}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      onChange={(event) => setStoryId(event.target.value)}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    >\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      {stories.map((story) => (\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        <option key={story.id} value={story.id}>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                          {story.name}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        </option>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      ))}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    </select>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                  </label>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                ) : null}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                {blocks.map((block, index) => (\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                  <div\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    key={`${block.title ?? 'block'}-${index}`}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    className={styles.block}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                  >\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    <div className={styles.blockHeading}>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      <strong>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        {block.title ?? t(locale, 'planImport.blockUntitled')}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      </strong>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      <button\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        type=\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"button\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        className={styles.applyButton}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        data-testid={`plan-import-apply-${index}`}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        onClick={() => apply(block)}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      >\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        {t(locale, 'planImport.apply')}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      </button>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    </div>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    <p className={styles.muted}>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      {`${t(locale, 'planImport.placements')}: ${block.placements.length}`}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                      {block.unplacedMarks.length > 0\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        ? ` / ${t(locale, 'planImport.unplaced')}: ${block.unplacedMarks.join('・')}`\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                        : ''}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    </p>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                  </div>\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                ))}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                {elevations.map((candidate, index) => (\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                  <Elevation\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    key={index}\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\n                    can